  '#!/usr/bin/env python3\n"""Serve the page-browser commands on the Chromium showing on this computer\'s DISPLAY.\n\nagent-browser (pinned in the image) attaches to that Chromium over CDP and browses. This wrapper\nkeeps Rakazo\'s contract and policy on top: which tab, refs that must still name the element the\nbot saw, the snapshot\'s size, masked secrets, upload confinement, and the computer_act fallback.\nSaved logins, cards and pay tokens go through page_secrets instead.\n"""\n\nfrom __future__ import annotations\n\nimport contextlib\nimport json\nimport math\nimport mimetypes\nimport os\nimport re\nimport socket\nimport stat\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\nimport unicodedata\nimport urllib.request\nfrom typing import Any, Callable\nfrom urllib.parse import unquote, urljoin, urlsplit\n\nsys.path[:0] = [os.path.dirname(os.path.realpath(__file__)), "/usr/local/lib/rakazo"]\nimport page_secrets  # noqa: E402\nimport rakazo_page_browser_recovery as recovery  # noqa: E402\nfrom page_secrets import CardFieldUncertain, Refused, payment_frame_origin  # noqa: E402\n\ndiscover_ws_url = page_secrets.discover_ws_url\n\nAGENT_BROWSER = os.environ.get("RAKAZO_AGENT_BROWSER") or "/usr/local/bin/agent-browser"\n\nNO_ANSWER = "The page did not answer in time."\nSTALE_REF = "Stale element ref: the page has changed since that snapshot. Use a ref from the page below."\nNOT_KEPT = "The page did not keep every character typed. Check the field in this snapshot before trying again."\nDISABLED = "That control is disabled, so nothing happened. Pick another control from this snapshot."\nPAYMENT_FRAME_HINT = "Card fields are in a payment frame: use fill_card without ref."\n\n# The snapshot goes to the model whole, in one piece of at most 12,000 characters, or the tool result\n# shortener cuts out its middle. So the control list and the page text share a budget, measured as\n# they will be sent (with their line breaks escaped).\nTREE_BUDGET = 10000\nCONTROLS_BUDGET = 5500\nMAX_CONTROLS = 80\nMIN_TEXT = 1500\nMAX_OPTIONS = 100\nOPTIONS_CHARS = 2000\nMAX_OPTION_TEXT = 80\n# A long page\'s controls are sampled this many times to find the ones in view.\nVIEW_PROBES = 48\n# How much of the text before a control a query also looks in, such as its heading.\nNEARBY_CHARS = 300\n# A match brings the rest of its form, unless the form is this big.\nMAX_FORM_CONTROLS = 30\nCUT_CONTROLS = "Snapshot with a query to find the rest."\n\nSETTLE_SECONDS = 3.0\n# The most an action\'s result waits for its requests and the snapshot after them together.\nACTION_WAIT_SECONDS = 2.0\n# A page is quiet once none of its requests has begun or finished for this long, none is still waiting\n# for its answer, and, after an action, this long has passed since its last step. Reading the page\n# runs on its main thread, so it already waits for scripts that are still running.\nQUIET_SECONDS = 0.15\n# How often a wait reads the page again.\nPOLL_SECONDS = 0.05\n# A search box or autocomplete sends its request a moment after typing stops (a debounce), so an act\n# that ends by typing starts its quiet wait this long after the last key.\nTYPING_PAUSE_SECONDS = 0.35\n# A request still unanswered after this long is a stream or a lost request, not the page loading.\nREQUEST_PATIENCE_SECONDS = 10.0\n# browser_navigate returns the page as an action does when the navigation took less than\n# NAVIGATE_SNAPSHOT_BY; the snapshot then ends by NAVIGATE_SNAPSHOT_UNTIL or is left out, inside\n# the supervisor\'s limit on one call.\nNAVIGATE_SECONDS = 15.0\nNAVIGATE_SNAPSHOT_BY = 12.0\nNAVIGATE_SNAPSHOT_UNTIL = 20.0\n# Typing presses each key after checking the page is still the same one with focus in the field.\n# Longer text is typed in one go and checked after.\nCHECKED_KEYS = 32\n\nMAX_UPLOAD_FILES = 10\nMAX_UPLOAD_BYTES = 100 * 1024 * 1024\n\n# agent-browser errors raised before anything reached the page: the step is settled.\nSETTLED_ERRORS = ("Unknown ref", "is stale", "cannot be recovered", "Could not locate element", "is covered by",\n                  "so the click would not reach it", "No option matched", "Element not found")\n\n\nclass Settled(RuntimeError):\n    """A step the page cannot take as asked (stale ref, covered or disabled element, no such option).\n\n    Nothing changed, and the result carries the page as it is, so the bot can choose again.\n    """\n\n\nclass TypingStopped(RuntimeError):\n    """Typing ended before the last key. The message never repeats any of the text."""\n\n\nclass KeysNotKept(RuntimeError):\n    """Every key was pressed, but the field did not keep them all: the step ran, its result is wrong."""\n\n\nclass AbError(RuntimeError):\n    def __init__(self, message: str, index: int = 0) -> None:\n        super().__init__(message)\n        self.index = index\n\n\ndef display_num() -> int:\n    raw = os.environ.get("DISPLAY", ":1")\n    try:\n        return int(str(raw).lstrip(":").split(".")[0] or "1")\n    except ValueError:\n        return 1\n\n\ndef cdp_port() -> int:\n    override = os.environ.get("RAKAZO_CDP_PORT")\n    if override:\n        return int(override)\n    # rakazo-browser uses 9221 + display number (:1 -> 9222).\n    return 9221 + display_num()\n\n\ndef http_get_json(url: str, timeout: float = 5.0) -> Any:\n    with urllib.request.urlopen(url, timeout=timeout) as resp:\n        data = resp.read(1024 * 1024 + 1)\n        if len(data) > 1024 * 1024:\n            raise RuntimeError("CDP discovery response too large")\n        return json.loads(data.decode("utf-8"))\n\n\ndef browser_closed(port: int) -> bool:\n    """Whether nothing listens on the browser\'s debugging port: no browser is running."""\n    try:\n        socket.create_connection(("127.0.0.1", port), timeout=0.3).close()\n    except ConnectionRefusedError:\n        return True\n    except OSError:\n        return False\n    return False\n\n\ndef wait_for_cdp(port: int, timeout_s: float = 3.0) -> Any:\n    """The browser\'s version answer, once it answers."""\n    deadline = time.time() + timeout_s\n    last_error = "unreachable"\n    while time.time() < deadline:\n        try:\n            return http_get_json(f"http://127.0.0.1:{port}/json/version", timeout=1.0)\n        except Exception as exc:  # noqa: BLE001\n            last_error = str(exc)\n            time.sleep(0.25)\n    raise RuntimeError(f"CDP not ready on port {port}: {last_error}")\n\n\n# Chromium\'s own pages, such as the new tab page, which agent-browser leaves alone.\nINTERNAL_SCHEMES = ("chrome", "chrome-extension", "chrome-untrusted", "chrome-search", "devtools")\nINTERNAL_PAGE = "The browser is showing one of its own pages, which the page tools cannot read. Open a site with browser_navigate."\n\n\ndef page_tabs(port: int) -> list[dict[str, Any]]:\n    """The browser\'s tabs: Chromium lists them by when they were last brought to the front."""\n    return [target for target in http_get_json(f"http://127.0.0.1:{port}/json/list")\n            if isinstance(target, dict) and target.get("type") == "page"]\n\n\nNO_TAB = "No browser tab is open. Use desktop tools to open one."\n\n\ndef front_tab(port: int) -> tuple[str, str]:\n    """The tab the person sees, and its address."""\n    for target in page_tabs(port):\n        return str(target["id"]), str(target.get("url") or "")\n    raise RuntimeError(NO_TAB)\n\n\n# A page may open tabs: a pop-up, a link to a new tab, or a report it opens once it has made it.\n# agent-browser follows a tab that opens in front, so the bot is told. More than MAX_NEW_TABS at once\n# is a flood, not a report: they are closed, and the bot\'s own tab is in front again. Of the tabs pages\n# opened, at most MAX_OPENED_TABS stay open; the ones longest out of sight are closed first.\nMAX_NEW_TABS = 3\nMAX_OPENED_TABS = 8\n# agent-browser stops answering for good when the tab its session reads is closed under it, so the\n# session moves to a tab that stays before any is closed. Closing tabs, moving the session and reading\n# the bot\'s tab again share one deadline per step, so a flood never holds a call much longer.\nTAB_WORK_SECONDS = 8.0\n# Tab work ends by then, after the helper started, so the call still fits the supervisor\'s 25 seconds.\nTABS_DONE_BY = 20.0\nREREAD_FAILED = ("The page opened tabs that were closed, and this tab could not be read again in time. "\n                 "Take a snapshot to read it.")\n\n\ndef left(deadline: float | None, most: float) -> float:\n    """A wait of at most `most` seconds that ends by the deadline, and a short one once it has passed."""\n    return most if deadline is None else max(0.2, min(most, deadline - time.monotonic()))\n\n\nclass Tabs:\n    """The browser\'s tabs at the end of the last call, kept in the page browser\'s own folder."""\n\n    def __init__(self, home: str, port: int, browser_id: Any, select: Callable[[Any], None]) -> None:\n        self.path, self.port, self.browser_id = os.path.join(home, f"tabs-{port}.json"), port, browser_id\n        # Points agent-browser\'s session at a tab, before tabs are closed.\n        self.select = select\n        try:\n            with open(self.path, encoding="utf-8") as file:\n                last = json.load(file)\n            # A browser started again has new tabs only, and may have restored the person\'s own.\n            self.known: set[Any] | None = set(last["tabs"]) if last["browser"] == browser_id else None\n            self.opened: list[Any] = list(last.get("opened") or []) if self.known is not None else []\n        except (OSError, ValueError, TypeError, KeyError, AttributeError):\n            self.known, self.opened = None, []\n        self.closed = self.trimmed = 0\n        self.start: set[Any] = set()\n        self.deadline: float | None = None\n\n    def begin(self) -> None:\n        """Close a flood of tabs opened since the last call, before the call picks its tab."""\n        tabs = page_tabs(self.port)\n        if self.known is not None:\n            # The tab in front of those the last call left, or else the tab in front, which stays.\n            keep = next((tab.get("id") for tab in tabs if tab.get("id") in self.known),\n                        tabs[0].get("id") if tabs else None)\n            # Kept as known, so it is not counted as page-opened and trimmed later.\n            self.known.add(keep)\n            tabs = self.close_flood(tabs, self.known, keep)\n        self.start = {tab.get("id") for tab in tabs}\n\n    def end(self, own: str, ours: str | None = None) -> tuple[list[dict[str, Any]], list[dict[str, Any]], bool]:\n        """The tabs now, the ones opened since the last call (or, for a browser started again, every\n        tab but this call\'s own), and whether tabs opened during the call were closed. The call\'s own\n        tab is never closed."""\n        tabs = page_tabs(self.port)\n        closed = self.closed\n        tabs = self.close_flood(tabs, self.start | {own}, own)\n        before = self.known if self.known is not None else {own}\n        opened = [tab for tab in tabs if tab.get("id") not in before and tab.get("id") != ours]\n        if self.known is not None:\n            ids = {tab.get("id") for tab in tabs}\n            self.opened = [tab for tab in self.opened if tab in ids] + [tab.get("id") for tab in opened]\n            tabs = self.trim(tabs, own)\n        flooded = self.closed > closed\n        if flooded:\n            with contextlib.suppress(OSError):\n                urllib.request.urlopen(f"http://127.0.0.1:{self.port}/json/activate/{own}",\n                                       timeout=left(self.deadline, 5.0)).close()\n                tabs = page_tabs(self.port)\n        # By id, as the tabs listed again: tab_note tells the one in front by identity.\n        current = {tab.get("id"): tab for tab in tabs}\n        opened = [current[tab.get("id")] for tab in opened if tab.get("id") in current]\n        # Written whole, then moved into place: a reader never sees half of it.\n        temporary = f"{self.path}.{os.getpid()}"\n        with open(temporary, "w", encoding="utf-8") as file:\n            json.dump({"browser": self.browser_id, "tabs": [tab.get("id") for tab in tabs], "opened": self.opened}, file)\n        os.replace(temporary, self.path)\n        return tabs, opened, flooded\n\n    def close(self, ids: list[Any], keep: Any) -> list[Any]:\n        """The tabs it closed, by the deadline: the rest are left for the next call."""\n        if keep is not None:\n            # Best effort: if the session does not move, the tab it reads is read again or refused after.\n            with contextlib.suppress(Exception):\n                self.select(keep)\n        closed = []\n        for tab in ids:\n            if self.deadline is not None and time.monotonic() >= self.deadline:\n                break\n            with contextlib.suppress(OSError):\n                urllib.request.urlopen(f"http://127.0.0.1:{self.port}/json/close/{tab}",\n                                       timeout=left(self.deadline, 5.0)).close()\n                closed.append(tab)\n        return closed\n\n    def close_flood(self, tabs: list[dict[str, Any]], before: set[Any], own: Any) -> list[dict[str, Any]]:\n        new = [tab.get("id") for tab in tabs if tab.get("id") not in before and tab.get("id") != own]\n        if len(new) <= MAX_NEW_TABS:\n            return tabs\n        self.closed += len(self.close(new, own))\n        return page_tabs(self.port)\n\n    def trim(self, tabs: list[dict[str, Any]], own: str) -> list[dict[str, Any]]:\n        """Close the tabs pages opened beyond MAX_OPENED_TABS, longest out of sight first. Tabs no page\n        opened, such as the person\'s own, are left alone."""\n        by_sight = [tab.get("id") for tab in tabs if tab.get("id") in self.opened and tab.get("id") != own]\n        extra = by_sight[MAX_OPENED_TABS:]\n        if not extra:\n            return tabs\n        # The tab in front stays, as the oldest out of sight go: the session stays on it.\n        closed = self.close(extra, tabs[0].get("id"))\n        self.trimmed += len(closed)\n        self.opened = [tab for tab in self.opened if tab not in closed]\n        return page_tabs(self.port)\n\n    def note(self, tabs: list[dict[str, Any]], opened: list[dict[str, Any]], shown_url: Any) -> str | None:\n        closed = (f"The page opened {self.closed} tabs at once, more than {MAX_NEW_TABS}, so they were closed."\n                  if self.closed else None)\n        trimmed = None if not self.trimmed else (\n            f"Closed the oldest tab a page had opened, to keep at most {MAX_OPENED_TABS}." if self.trimmed == 1\n            else f"Closed the {self.trimmed} oldest tabs pages had opened, to keep at most {MAX_OPENED_TABS}.")\n        return " ".join(filter(None, [closed, trimmed, tab_note(opened, tabs, shown_url)])) or None\n\n\ndef tab_named(tab: dict[str, Any]) -> str:\n    return f"{json.dumps(str(tab.get(\'title\') or \'\')[:200], ensure_ascii=False)} at {str(tab.get(\'url\') or \'\')[:500]}"\n\n\ndef tab_note(opened: list[dict[str, Any]], tabs: list[dict[str, Any]], shown_url: Any) -> str | None:\n    """Tells the bot which tabs opened: agent-browser follows a tab that opens in front, so the page tools read it."""\n    if not opened:\n        return None\n    front = tabs[0]\n    others = [tab for tab in opened if tab is not front]\n    listed = "; ".join(tab_named(tab) for tab in others[:3]) + (f"; and {len(others) - 3} more" if len(others) > 3 else "")\n    if front not in opened:\n        return f"{\'A new tab\' if len(opened) == 1 else f\'{len(opened)} new tabs\'} opened behind this one: {listed}."\n    if not others:\n        return (f"A new tab opened, and page tools now read it: {tab_named(front)}; the tab before it is still open."\n                + ("" if shown_url == front.get("url") else " Take a snapshot to read it."))\n    return (f"{len(opened)} new tabs opened, and page tools now read the one in front: {tab_named(front)}; "\n            f"the others are {listed}; the tabs before them are still open."\n            + ("" if shown_url == front.get("url") else " Take a snapshot to read it."))\n\n\ndef internal(url: str) -> bool:\n    return urlsplit(url).scheme in INTERNAL_SCHEMES\n\n\ndef check_url(url: str) -> None:\n    parsed = urlsplit(url)\n    if parsed.scheme not in ("http", "https") or parsed.username or parsed.password:\n        raise RuntimeError("Only HTTP(S) URLs without embedded credentials are supported")\n\n\nclass AgentBrowser:\n    """agent-browser\'s session for this display: one daemon, kept attached between calls."""\n\n    def __init__(self, port: int) -> None:\n        self.port = port\n        self.home = os.path.join(tempfile.gettempdir(), f"rakazo-ab-{os.getuid()}")\n        os.makedirs(self.home, mode=0o700, exist_ok=True)\n        info = os.lstat(self.home)\n        if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid():\n            raise RuntimeError("The page browser\'s own folder is not this user\'s")\n        # Its own configuration, never one from the bot\'s home or working folder.\n        self.config = os.path.join(self.home, "config.json")\n        with open(self.config, "w", encoding="utf-8") as config:\n            config.write("{}")\n        self.session = f"display-{port}"\n        self.client: CdpClient | None = None\n        self.session_id: str | None = None\n        # When set, every command answers by then or is given up.\n        self.deadline: float | None = None\n        self.env = {key: value for key, value in os.environ.items()\n                    if key in ("LANG", "LD_PRELOAD", "NSS_WRAPPER_PASSWD", "NSS_WRAPPER_GROUP")}\n        self.env.update({\n            "PATH": "/usr/local/bin:/usr/bin:/bin",\n            "HOME": self.home,\n            "AGENT_BROWSER_CONFIG": self.config,\n            "AGENT_BROWSER_SOCKET_DIR": self.home,\n            "AGENT_BROWSER_SESSION": self.session,\n            # Always the Chromium on this display: without it, agent-browser would start a browser of its own.\n            "AGENT_BROWSER_CDP": str(port),\n            "AGENT_BROWSER_IDLE_TIMEOUT_MS": "900000",\n            # Dialogs are the person\'s and the page\'s to answer, as on the screen; see PageBrowser.dialog_result.\n            "AGENT_BROWSER_NO_AUTO_DIALOG": "1",\n            "AGENT_BROWSER_NO_WEBMCP": "1",\n        })\n\n    def batch(self, commands: list[list[str]], *, timeout: float = 20.0, bail: bool = True) -> list[Any]:\n        """Each command\'s result, in one agent-browser call. Commands and their text go over stdin, not argv."""\n        if self.client is not None and self.client.deadline is not None:\n            timeout = min(timeout, self.client.deadline - time.time())\n        if timeout <= 0:\n            if self.client is not None:\n                self.client.last_timeout = self.session_id or ""\n            raise TimeoutError(NO_ANSWER)\n        try:\n            proc = subprocess.run(\n                [AGENT_BROWSER, "batch", "--json", "--omit-command", *(["--bail"] if bail else [])],\n                input=json.dumps(commands), capture_output=True, text=True, env=self.env, cwd=self.home,\n                timeout=left(self.deadline, timeout))\n        except subprocess.TimeoutExpired:\n            if self.client is not None:\n                self.client.last_timeout = self.session_id or ""\n            raise TimeoutError(NO_ANSWER) from None\n        try:\n            items = json.loads(proc.stdout)\n        except json.JSONDecodeError:\n            raise AbError((proc.stderr or proc.stdout).strip()[:500] or "agent-browser gave no answer") from None\n        if not isinstance(items, list):\n            raise AbError(str((items or {}).get("error") if isinstance(items, dict) else items)[:500])\n        results: list[Any] = []\n        for index, item in enumerate(items):\n            if not isinstance(item, dict):\n                raise AbError("agent-browser gave no answer", index)\n            data = item.get("result") if isinstance(item.get("result"), dict) else {}\n            # Only ever the browser on the screen: a page agent-browser opened itself is not the bot\'s.\n            if (data.get("lifecycle") or {}).get("launched") is True:\n                raise RuntimeError("Page browser is not attached to this computer\'s Chrome.")\n            if not item.get("success"):\n                if bail:\n                    raise AbError(str(item.get("error") or "agent-browser failed"), index)\n                results.append(None)\n                continue\n            results.append(data)\n        if len(results) < len(commands):\n            raise AbError("agent-browser stopped early", len(results))\n        return results\n\n    def session_tab(self) -> str | None:\n        """The tab the session reads now; it also follows tabs opened while it was attached."""\n        # One answer or none: a probe that hangs must leave the call\'s short budget to the work after it.\n        try:\n            proc = subprocess.run(\n                [AGENT_BROWSER, "tab", "list", "--json"], capture_output=True, text=True,\n                env=self.env, cwd=self.home, timeout=left(self.deadline, 1.0))\n            envelope = json.loads(proc.stdout)\n            data = envelope.get("data") if isinstance(envelope, dict) else None\n            tabs = data.get("tabs") if isinstance(data, dict) else None\n        except (OSError, subprocess.SubprocessError, json.JSONDecodeError):\n            return None\n        for tab in tabs if isinstance(tabs, list) else []:\n            if isinstance(tab, dict) and tab.get("active") and tab.get("type") == "page":\n                return str(tab.get("targetId"))\n        return None\n\n    def use_tab(self, target_id: str) -> None:\n        """Point the session at the tab on screen when the person has switched tabs since the last call.\n\n        agent-browser follows a newly opened tab on its own, so the tab it was last pointed at is\n        not enough: ask where the session is and move it only when it reads another tab.\n        """\n        if self.session_tab() == target_id:\n            return\n        self.batch([["tab", target_id]])\n\n\n# A navigation as from the address bar: no referrer leaves for the next site.\nNAVIGATE = r"""(() => {\n  const timeOrigin = performance.timeOrigin;\n  const policy = document.createElement("meta");\n  policy.name = "referrer";\n  policy.content = "no-referrer";\n  (document.head || document.documentElement).append(policy);\n  // After this script has answered: a page being replaced answers late.\n  setTimeout(() => location.assign(URL), 0);\n  return { timeOrigin, href: location.href };\n})()"""\n\n# Whether the page has loaded, when its document began, and the requests it has finished (failed ones\n# included) with when each ended.\nPAGE_LOAD = r"""({ href: location.href, ready: document.readyState, began: performance.timeOrigin,\n  done: performance.getEntriesByType("resource").slice(-500)\n    .map((entry) => [entry.name, performance.timeOrigin + entry.responseEnd]) })"""\n\n# The page\'s address, title and text, the values a snapshot must not show (password fields, fields\n# holding a saved login or card, and fields drawn as dots), and the merchant account a pay token checkout names in the page itself.\nPAGE_STATE = r"""(() => {\n  const masked = [...document.querySelectorAll("input, textarea")]\n    .filter((el) => el.value && (el.type === "password" || el.hasAttribute("data-rakazo-filled")\n      || getComputedStyle(el).webkitTextSecurity !== "none"))\n    .map((el) => el.value);\n  const blocks = [...document.querySelectorAll(".AiAgentPaymentSteering")]\n    .filter((block) => block.querySelector(\'input[name="link_pay_token"]\'));\n  const holder = blocks.length !== 1 ? null : blocks[0].matches("[data-stripe-merchant-account]") ? blocks[0]\n    : blocks[0].querySelector("[data-stripe-merchant-account]");\n  const account = holder?.getAttribute("data-stripe-merchant-account") || "";\n  return {\n    url: location.href,\n    title: (document.title || "").slice(0, 200),\n    ready: document.readyState,\n    text: (document.body?.innerText || "").slice(0, 200000),\n    masked,\n    payToken: /^acct_[A-Za-z0-9]{1,64}$/.test(account) ? account : null,\n    frames: [...document.querySelectorAll("iframe")].slice(0, 50).map((frame) => frame.src),\n  };\n})()"""\n\n\nclass Node:\n    """One line of agent-browser\'s snapshot: role, name, [attributes], what follows, and its value."""\n\n    def __init__(self, depth: int, role: str, name: str = "", attrs: str = "", extra: str = "",\n                 value: str | None = None) -> None:\n        self.depth, self.role, self.name, self.attrs, self.extra, self.value = depth, role, name, attrs, extra, value\n        self.children: list[Node] = []\n        self.parent: Node | None = None\n\n    @property\n    def frame(self) -> Node | None:\n        """The frame element this element\'s page is in, when it is inside one."""\n        at = self.parent\n        while at is not None and not (at.role == "Iframe" and at.ref):\n            at = at.parent\n        return at\n\n    @property\n    def ref(self) -> str | None:\n        found = re.search(r"\\bref=(e\\d+)\\b", self.attrs)\n        return found.group(1) if found else None\n\n\nLINE = re.compile(r"^(?P<indent> *)- (?P<role>[^\\s\\"\\[]+)(?P<rest>.*)$")\n\n\ndef parse_line(text: str) -> Node | None:\n    match = LINE.match(text)\n    if not match:\n        return None\n    rest, name = match["rest"], ""\n    if rest.startswith(\' "\'):\n        try:\n            name, end = json.JSONDecoder().raw_decode(rest, 1)\n            rest = rest[end:]\n        except json.JSONDecodeError:\n            end = rest.rfind(\'" [\')\n            name, rest = (rest[2:end], rest[end + 1:]) if end > 1 else (rest[2:].rstrip(\'"\'), "")\n    attrs = ""\n    if rest.startswith(" ["):\n        close = rest.find("]")\n        if close > 0:\n            attrs, rest = rest[2:close], rest[close + 1:]\n    value = None\n    if ": " in rest:\n        rest, value = rest.split(": ", 1)\n    return Node(len(match["indent"]) // 2, match["role"], " ".join(str(name).split()), attrs, rest, value)\n\n\ndef parse_tree(text: str) -> list[Node]:\n    roots: list[Node] = []\n    stack: list[Node] = []\n    for line in str(text or "").splitlines():\n        node = parse_line(line)\n        if node is None:\n            continue\n        while stack and stack[-1].depth >= node.depth:\n            stack.pop()\n        if stack:\n            node.parent = stack[-1]\n        (stack[-1].children if stack else roots).append(node)\n        stack.append(node)\n    return roots\n\n\ndef walk(nodes: list[Node]):  # type: ignore[no-untyped-def]\n    for node in nodes:\n        yield node\n        yield from walk(node.children)\n\n\ndef find_ref(nodes: list[Node], ref: str) -> Node | None:\n    return next((node for node in walk(nodes) if node.ref == ref), None)\n\n\ndef native_options(node: Node) -> list[Node]:\n    """A native dropdown\'s options, which the snapshot lists under it."""\n    if node.role != "combobox":\n        return []\n    return [child for child in walk(node.children) if child.role == "option"]\n\n\ndef sent(text: str) -> int:\n    """A text\'s length as the bot receives it, line breaks escaped."""\n    return len(json.dumps(text, ensure_ascii=False)) - 2\n\n\ndef cut_option(text: str) -> str:\n    # A long option keeps its start and its end, which is where long options usually differ.\n    return f"{text[:50]}…{text[-(MAX_OPTION_TEXT - 51):]}" if len(text) > MAX_OPTION_TEXT else text\n\n\ndef options_of(node: Node) -> tuple[list[dict[str, Any]], int]:\n    """A dropdown\'s options as the page shows them: the first MAX_OPTIONS and the chosen one."""\n    every = native_options(node)\n    shown = every[:MAX_OPTIONS]\n    chosen = next((option for option in every if "selected" in option.attrs.split(", ")), None)\n    if chosen is not None and chosen not in shown:\n        shown.append(chosen)\n    options = []\n    for option in shown:\n        label = cut_option(" ".join(option.name.split()))\n        attrs = option.attrs.split(", ")\n        options.append({"label": label, "value": label, **({"selected": True} if "selected" in attrs else {}),\n                        **({"disabled": True} if "disabled" in attrs else {})})\n    return options, len(every)\n\n\ndef describe_options(options: list[dict[str, Any]], total: int) -> str:\n    """The options a model reads, as many as fit; the chosen one is always shown."""\n    def describe(option: dict[str, Any]) -> str:\n        return (json.dumps(option["label"], ensure_ascii=False) + (" (selected)" if option.get("selected") else "")\n                + (" (disabled)" if option.get("disabled") else ""))\n    parts: list[str] = []\n    used = 0\n    for option in options:\n        part = describe(option)\n        if parts and used + len(part) > OPTIONS_CHARS:\n            break\n        parts.append(part)\n        used += len(part) + 2\n    chosen = next((option for option in options if option.get("selected")), None)\n    if chosen is not None and describe(chosen) not in parts:\n        parts.append(describe(chosen))\n    return ", ".join(parts) + (f", and {total - len(parts)} more" if total > len(parts) else "")\n\n\nCONTROL_ROLES = frozenset({"button", "link", "textbox", "searchbox", "checkbox", "radio", "combobox", "listbox",\n                           "option", "menuitem", "menuitemcheckbox", "menuitemradio", "tab", "switch", "slider",\n                           "spinbutton", "treeitem", "Iframe"})\n\n\nclass Control:\n    """A control as the snapshot lists it, with the text a query can find it by."""\n\n    def __init__(self, index: int, line: str, entry: dict[str, Any], node: Node, own: str, nearby: str) -> None:\n        self.index, self.line, self.entry, self.node, self.own, self.nearby = index, line, entry, node, own, nearby\n        self.cost = sent(line) + 1\n\n\ndef words(text: str) -> list[str]:\n    plain = unicodedata.normalize("NFKD", text.casefold())\n    return re.sub(r"[^\\w]+", " ", "".join(char for char in plain if not unicodedata.combining(char))).split()\n\n\ndef found(word: str, among: list[str]) -> bool:\n    """A query word is a word of the text, or the start of one once it is long enough to mean something."""\n    return any(have == word or (len(word) >= 3 and have.startswith(word)) for have in among)\n\n\n# The containers a control\'s form is: a match brings the rest of it, such as the form\'s submit button.\nFORM_ROLES = frozenset({"form", "group", "search", "dialog", "alertdialog", "radiogroup"})\n\n\ndef matching(controls: list[Control], query: str) -> list[Control]:\n    """The controls a query names, best first: those with every word in their own name, label, value or\n    options, then those that need the text before them or their form\'s name, then the rest of their forms.\n\n    When none has every word, those with the most do.\n    """\n    wanted = list(dict.fromkeys(words(query)))\n    if not wanted:\n        return []\n    position = {id(control.node): index for index, control in enumerate(controls)}\n    scored: list[tuple[int, int, int]] = []\n    for index, control in enumerate(controls):\n        own = words(control.own)\n        around = own + words(control.nearby)\n        at = control.node.parent\n        while at is not None:\n            around += words(at.name)\n            at = at.parent\n        hits = sum(found(word, around) for word in wanted)\n        if hits:\n            scored.append((hits, sum(found(word, own) for word in wanted), index))\n    if not scored:\n        return []\n    best = max(hits for hits, _, _ in scored)\n    ranked = [index for hits, _, index in sorted(scored, key=lambda s: (-s[1], s[2])) if hits == best]\n    chosen = dict.fromkeys(ranked)\n    for index in ranked:\n        form = form_of(controls[index].node)\n        if form is not None:\n            mates = [position[id(node)] for node in walk(form.children) if id(node) in position]\n            if len(mates) <= MAX_FORM_CONTROLS:\n                chosen.update(dict.fromkeys(mates))\n    listed: dict[int, None] = {}\n    for index in chosen:\n        # A control in a frame comes after the frame\'s line, which names its site, so a cut never parts them.\n        frames: list[int] = []\n        frame = controls[index].node.frame\n        while frame is not None:\n            if id(frame) in position:\n                frames.append(position[id(frame)])\n            frame = frame.frame\n        listed.update(dict.fromkeys([*reversed(frames), index]))\n    return [controls[index] for index in listed]\n\n\ndef form_of(node: Node) -> Node | None:\n    """The form a control is in, or else the nearest group-like container."""\n    nearest = None\n    at = node.parent\n    while at is not None:\n        if at.role == "form":\n            return at\n        if nearest is None and at.role in FORM_ROLES:\n            nearest = at\n        at = at.parent\n    return nearest\n\n\ndef fit(candidates: list[Control], budget: int) -> list[Control]:\n    """The candidates that fit, taken in order until one does not, then put back in page order."""\n    shown: list[Control] = []\n    used = 0\n    for control in candidates:\n        if len(shown) >= MAX_CONTROLS or (shown and used + control.cost > budget):\n            break\n        shown.append(control)\n        used += control.cost\n    return sorted(shown, key=lambda control: control.index)\n\n\ndef same_site(url: Any) -> str:\n    """The site a URL is on, as its host\'s last two labels; close enough to tell a page\'s own requests apart."""\n    try:\n        host = urlsplit(str(url or "")).hostname or ""\n    except ValueError:\n        return ""\n    return ".".join(host.split(".")[-2:])\n\n\ndef unframed(text: str) -> str:\n    """Page text with anything that reads like a frame\'s header line set apart, so a page cannot name a site."""\n    return text.replace("[frame ", "[ frame ")\n\n\ndef frame_site(src: Any) -> str:\n    try:\n        parts = urlsplit(str(src or ""))\n        return f"{parts.scheme}://{parts.netloc.rpartition(\'@\')[2]}" if parts.scheme in ("http", "https") else ""\n    except ValueError:\n        return ""\n\n\n# A PDF a tab shows, such as a report a page opened in a new tab, is in the browser\'s viewer, which the\n# page tools cannot read. It is saved as a download of the tab\'s own address, once per document, so\n# the bot reads the file instead.\nSAVE_PDF = r"""(() => {\n  if (document.contentType !== "application/pdf" || window.__rakazoPdfSaved) return false;\n  window.__rakazoPdfSaved = true;\n  const link = document.createElement("a");\n  link.href = location.href;\n  link.download = NAME;\n  document.documentElement.append(link);\n  link.click();\n  link.remove();\n  return true;\n})()"""\n\n\nclass PageBrowser:\n    def __init__(self, port: int, target_id: str, browser: AgentBrowser,\n                 client: CdpClient | None = None, session_id: str | None = None) -> None:\n        self.port, self.target, self.ab = port, target_id, browser\n        self.client, self.session_id = client, session_id\n        self.downloads: Downloads | None = None\n        # Set by a step whose input opened a JavaScript dialog. Reading a page that a dialog blocks\n        # times out, and agent-browser then stops answering for the tab, dialog commands included.\n        self.dialog_opened = False\n        self._purchases: Purchases | None = None\n\n    # -- reading the page -------------------------------------------------------------------------\n\n    def pending_requests(self) -> tuple[bool, float, bool]:\n        """Whether the page is waiting on a request of its current document, when its latest began or\n        ended, and whether the page may be waiting on requests the log never saw.\n\n        agent-browser logs requests only from when its session attached, which can be after the page\n        began loading: the person opened it, or the session started or moved to this tab since.\n        """\n        state, log = self.ab.batch([["eval", PAGE_LOAD], ["network", "requests"]])\n        page = state.get("result") or {}\n        # agent-browser logs a response but never a failure; the page lists failed requests as done.\n        done = {str(name): float(ended or 0) for name, ended in page.get("done") or []}\n        requests = [r for r in log.get("requests") or [] if isinstance(r, dict)]\n        documents = [r for r in requests if r.get("resourceType") == "Document"]\n        current = [r for r in documents if r.get("url") == page.get("href")] or documents\n        since = float(current[-1].get("timestamp") or 0) if current else 0.0\n        now = time.time() * 1000\n        # The page\'s own requests: a third-party widget or beacon that hangs does not hold the page back.\n        site = same_site(page.get("href"))\n        recent = [r for r in requests if float(r.get("timestamp") or 0) >= since and same_site(r.get("url")) == site]\n        waiting = [r for r in recent if r.get("status") is None and r.get("url") not in done\n                   and r.get("resourceType") not in ("EventSource", "WebSocket")\n                   and now - float(r.get("timestamp") or 0) < REQUEST_PATIENCE_SECONDS * 1000]\n        started = [float(r.get("timestamp") or 0) for r in recent]\n        ended = [at for name, at in done.items() if at >= since and same_site(name) == site]\n        latest = max(started + ended, default=0.0)\n        unseen = (not any(r.get("url") == page.get("href") for r in documents)\n                  and now - float(page.get("began") or 0) < REQUEST_PATIENCE_SECONDS * 1000)\n        return bool(waiting) or page.get("ready") != "complete", latest / 1000, unseen\n\n    def settle(self, seconds: float, quiet_from: float = 0.0) -> bool:\n        """Wait until the page has loaded and its requests are answered, then QUIET_SECONDS more.\n\n        Many sites draw a signed-out shell first and replace it once their own requests return,\n        so a page captured earlier can show "Sign in" to an account that is signed in.\n        """\n        deadline = time.monotonic() + seconds\n        load: PageLoad | None = None\n        try:\n            while True:\n                busy, latest, unseen = self.pending_requests()\n                if not busy and unseen:\n                    load = load or PageLoad(self.port, self.target)\n                    busy = not load.idle()\n                quiet_in = QUIET_SECONDS - (time.time() - max(latest, quiet_from))\n                if not busy and quiet_in <= 0:\n                    # agent-browser keeps every request it sees; once none is waiting, the log can start over.\n                    self.ab.batch([["network", "requests", "--clear"]])\n                    return True\n                if time.monotonic() >= deadline:\n                    return not busy\n                # A quiet page is read again just as it has been quiet long enough.\n                wait = POLL_SECONDS if busy else min(POLL_SECONDS, quiet_in)\n                time.sleep(max(0.0, min(wait, deadline - time.monotonic())))\n        finally:\n            if load:\n                load.close()\n\n    def snapshot(self, settle: float | None = None, query: str | None = None) -> dict[str, Any]:\n        settled = self.settle(SETTLE_SECONDS if settle is None else settle)\n        state_result, snap = self.ab.batch([["eval", PAGE_STATE], ["snapshot"]])\n        state = state_result.get("result") or {}\n        roots = parse_tree(snap.get("snapshot") or "")\n        frames = [node for node in walk(roots) if node.role == "Iframe" and node.ref]\n        sources = self.ab.batch([["get", "attr", f"@{node.ref}", "src"] for node in frames], bail=False) if frames else []\n        sites = {id(node): frame_site(urljoin(str(state.get("url") or ""), str((found or {}).get("value") or "")))\n                 for node, found in zip(frames, sources)}\n        masked = {str(value) for value in state.get("masked") or [] if value}\n        # Found in the page, not in agent-browser\'s tree: a session that attached after a frame loaded never sees inside it.\n        payment = any(payment_frame_origin(frame_site(src)) for src in state.get("frames") or [])\n        try:\n            card_shown, account = page_secrets.payment_frame_hints(self.port, self.target) if payment else (False, None)\n        except Exception:  # noqa: BLE001\n            card_shown, account = False, None\n        hints: list[str] = []\n        frame_text: list[str] = []\n        controls: list[Control] = []\n        # Text read since the last control, such as a heading or a field\'s label: what a query can find it by.\n        recent: list[str] = []\n\n        def render(nodes: list[Node], depth: int, inside: str | None) -> None:\n            for node in nodes:\n                if node.role == "Iframe":\n                    site = sites.get(id(node), "")\n                    if payment_frame_origin(site):\n                        # Card details reach a payment provider\'s frame only through fill_card.\n                        continue\n                    text = " ".join(n.name for n in walk(node.children) if n.role == "StaticText").strip()\n                    if text:\n                        frame_text.append(f"[frame {site or \'unknown\'}]\\n{unframed(text)}")\n                if node.role == "option" and inside == "select":\n                    continue\n                ref = node.ref\n                # agent-browser also hands refs to named text such as headings and table cells; the\n                # list is of what a click or a fill can mean something for.\n                if ref is None or not (node.role in CONTROL_ROLES or "clickable" in node.extra):\n                    if node.name:\n                        recent.append(node.name)\n                    render(node.children, depth, inside)\n                    continue\n                value = node.value\n                if value is not None and (value in masked or set(value) <= {"•"}):\n                    value = None\n                entry: dict[str, Any] = {"ref": ref, "role": node.role, "name": node.name[:200]}\n                checked = re.search(r"\\bchecked=(true|false)\\b", node.attrs)\n                if value is not None and value != "":\n                    entry["value"] = value[:2000]\n                elif checked:\n                    entry["value"] = "checked" if checked.group(1) == "true" else "unchecked"\n                line = f"{\'  \' * depth}- {node.role}"\n                if node.name:\n                    line += " " + json.dumps(node.name[:100], ensure_ascii=False)\n                line += f" [{node.attrs}]{node.extra}"\n                if node.role == "Iframe" and sites.get(id(node)):\n                    line += f" {sites[id(node)]}"\n                if value is not None and value != "":\n                    line += ": " + value[:100]\n                options, total = options_of(node)\n                if options:\n                    entry["options"] = options\n                    if total > len(options):\n                        entry["optionsTotal"] = total\n                    line += " options: " + describe_options(options, total)\n                own = " ".join([node.name, entry.get("value") or "", *(option["label"] for option in options)])\n                controls.append(Control(len(controls), line, entry, node, own, " ".join(recent)[-NEARBY_CHARS:]))\n                recent.clear()\n                render(node.children, depth + 1, "select" if options else inside)\n\n        render(roots, 0, None)\n        if card_shown:\n            hints.append(PAYMENT_FRAME_HINT)\n        account = state.get("payToken") or account\n        if account:\n            hints.append(f\'This checkout accepts a pay token: merchantAccountId "{account}".\')\n        origins: list[str] = []\n        if self.client is not None and self.session_id is not None:\n            try:\n                origins = page_secrets.frame_origins(self.client, self.session_id)\n            except Exception:  # Missing evidence must never authorize revealing a secret.\n                pass\n        page = {"ok": True, "url": str(state.get("url") or snap.get("origin") or ""),\n                "title": str(state.get("title") or ""), "frameOrigins": origins,\n                **({} if settled else {"loading": True})}\n        if query:\n            ranked = matching(controls, query)\n            shown = fit(ranked, TREE_BUDGET - sum(sent(h) + 1 for h in hints) - 200)\n            label = json.dumps(query, ensure_ascii=False)\n            if not ranked:\n                notice = f"[no controls match {label}]"\n            elif len(shown) < len(ranked):\n                notice = f"[controls matching {label}: showing {len(shown)} of {len(ranked)}]"\n            else:\n                notice = f"[controls matching {label}]"\n            tree = "\\n".join([notice, *(c.line for c in shown), *hints])\n            return {**page, "tree": tree, "elements": [c.entry for c in shown]}\n        shown = fit(controls, CONTROLS_BUDGET)\n        start = self.view_start(controls) if len(shown) < len(controls) else 0\n        if start:\n            # From the first control in view on, then back up the page with the room left.\n            shown = fit(controls[start:] + controls[start - 1::-1], CONTROLS_BUDGET)\n        listing = "\\n".join(c.line for c in shown) or "(no interactive elements)"\n        notices = (f"[controls: showing {len(shown)} of {len(controls)}. {CUT_CONTROLS}]\\n"\n                   if len(shown) < len(controls) else "")\n        text = "\\n".join([unframed(str(state.get("text") or "")), *frame_text])\n        room = max(MIN_TEXT, TREE_BUDGET - sent(listing) - sent(notices) - sum(sent(h) + 1 for h in hints) - 200)\n        cut = len(text)\n        while cut > 0 and sent(text[:cut]) > room:\n            cut = int(cut * 0.9)\n        if cut < len(text):\n            notices += f"[page text: showing first {cut} of {len(text)} characters]\\n"\n        tree = notices + text[:cut] + "\\n" + listing + "".join("\\n" + hint for hint in hints)\n        return {**page, "tree": tree, "elements": [c.entry for c in shown]}\n\n    def view_start(self, controls: list[Control]) -> int:\n        """Where the controls in view begin: just after the last one above the visible part of the page.\n\n        Controls come in page order, which is mostly top to bottom, so a sample of them is enough.\n        Ones in frames are placed by their frame, and a header that stays on screen does not count.\n        """\n        top = [index for index, control in enumerate(controls) if control.node.frame is None]\n        sampled = range(0, len(top), max(1, math.ceil(len(top) / VIEW_PROBES)))\n        if not sampled:\n            return 0\n        try:\n            boxes = self.ab.batch([["get", "box", f"@{controls[top[at]].entry[\'ref\']}"] for at in sampled], bail=False)\n        except Exception:  # noqa: BLE001\n            return 0\n        start = 0\n        for at, box in zip(sampled, boxes):\n            if box and box.get("height") and float(box.get("y") or 0) + float(box["height"]) <= 0:\n                # The next control outside any frame: a frame above the view takes its own controls with it.\n                start = top[at + 1] if at + 1 < len(top) else len(controls)\n        return min(start, len(controls) - 1)\n\n    def control(self, ref: str, *, check_disabled: bool = False) -> Node:\n        """The element a ref names in the page as it is now; a ref that names nothing now is stale.\n\n        agent-browser keeps a ref while its element lives, but would hand an action a replacement\n        with the same role and name, even on another page. Checking right before the step stops that.\n        """\n        commands = [["snapshot", "-i"]]\n        if check_disabled:\n            # `is enabled` includes disabled fieldsets (and their first-legend exception),\n            # but agent-browser does not include aria-disabled in that check.\n            commands += [["is", "enabled", f"@{ref}"], ["get", "attr", f"@{ref}", "aria-disabled"]]\n        snap, *state = self.step(commands)\n        node = find_ref(parse_tree(snap.get("snapshot") or ""), ref)\n        if node is None or ref not in (snap.get("refs") or {}):\n            raise Settled(STALE_REF)\n        if check_disabled and (state[0].get("enabled") is False or str(state[1].get("value")).lower() == "true"):\n            raise Settled(DISABLED)\n        return node\n\n    def purchases(self) -> Purchases:\n        if self._purchases is None:\n            self._purchases = Purchases(self.port, self.target)\n        return self._purchases\n\n    def close(self) -> None:\n        if self._purchases:\n            self._purchases.close()\n\n    def click_purchase(self, ref: str, node: Node) -> tuple[str, dict[str, Any] | None]:\n        """The top page\'s host, the site the user sees, and what a click on ref would buy, or None.\n        A page that cannot be read asks."""\n        try:\n            purchases = self.purchases()\n            site = purchases.site()\n        except Exception:  # noqa: BLE001\n            return "", dict(UNREADABLE_PURCHASE)\n        if node.frame is not None:\n            # A control inside a frame is not placed on the page: the click asks whenever the page or any of\n            # its frames shows a payment.\n            try:\n                return site, purchases.signals(False, time.monotonic() + DESKTOP_DEADLINE_SECONDS)\n            except Exception:  # noqa: BLE001\n                return site, purchases.signals_or_ask(False)\n        for scrolled in (False, True):\n            try:\n                if scrolled:\n                    self.ab.batch([["scrollintoview", f"@{ref}"]])\n                (box,) = self.ab.batch([["get", "box", f"@{ref}"]])\n            except Exception:  # noqa: BLE001\n                box = None\n            try:\n                return site, purchases.click(box, scrolled)\n            except Offscreen:\n                continue\n        return site, None\n\n    def purchase_check(self, args: dict[str, Any]) -> dict[str, Any]:\n        """Which of these clicks would complete a purchase, or whether a click or key on the screen would.\n\n        Nothing is pressed. A ref that no longer names an element on the page counts as none: act asks again.\n        """\n        actions = args.get("actions") or []\n        if not isinstance(actions, list) or len(actions) > 24:\n            raise RuntimeError("Expected up to 24 actions")\n        site = self.purchases().site()\n        steps: list[int] = []\n        first: dict[str, Any] | None = None\n        for index, step in enumerate(actions):\n            if not isinstance(step, dict) or step.get("kind") != "click" or not isinstance(step.get("ref"), str):\n                continue\n            try:\n                node = self.control(step["ref"])\n            except Settled:\n                continue\n            site, found = self.click_purchase(step["ref"], node)\n            if found:\n                # One card approves one click: a later purchase click in the batch is refused, and asks.\n                steps, first = [index], found\n                break\n        if args.get("desktop") is True and not steps:\n            first = self.purchases().desktop(args)\n        purchase = {"steps": steps, "label": first.get("label", ""), "amount": first.get("amount", ""),\n                    "amountFrom": first.get("amountFrom", "page"), "reason": first.get("reason")} if first else None\n        return {"ok": True, "url": "", "title": "", **self.purchases().where(), "site": site, "purchase": purchase}\n\n    # -- commands ---------------------------------------------------------------------------------\n\n    def navigate(self, url: str, opened: bool = False) -> dict[str, Any]:\n        """Go to url, or, when `opened`, read the tab that was just opened on it."""\n        check_url(url)\n        started = time.monotonic()\n        before: dict[str, Any] = {}\n        same_document = opened\n        if not opened:\n            # agent-browser\'s own `open` holds its session until the load event, up to 25 seconds; the\n            # page is read while it is still loading instead, as the person would see it.\n            _, before = self.ab.batch([["network", "requests", "--clear"],\n                                       ["eval", NAVIGATE.replace("URL", json.dumps(url))]])\n            before = before.get("result") or {}\n            # Scripts run in a page that is being replaced answer late, so the new document\'s response is\n            # awaited in the request log first. A new fragment of the same page loads no document.\n            same_document = str(before.get("href") or "").split("#")[0] == url.split("#")[0] and "#" in url\n        while not same_document:\n            if self.downloads:\n                self.downloads.client.listen(0.01)\n                if self.downloads.client.downloads:\n                    return {"ok": True, **self.snapshot(0.0)}\n            (log,) = self.ab.batch([["network", "requests"]])\n            if any(r.get("resourceType") == "Document" and r.get("status") is not None\n                   for r in log.get("requests") or [] if isinstance(r, dict)):\n                break\n            if time.monotonic() - started > NAVIGATE_SECONDS:\n                raise RuntimeError("Navigation did not settle; inspect the screen before continuing")\n            time.sleep(POLL_SECONDS)\n        while True:\n            (now,) = self.ab.batch([["eval", "({ timeOrigin: performance.timeOrigin, href: location.href, "\n                                              "ready: document.readyState })"]])\n            now = now.get("result") or {}\n            if self.downloads:\n                self.downloads.client.listen(0.01)\n                if self.downloads.client.downloads:\n                    return {"ok": True, **self.snapshot(0.0)}\n            moved = opened or now.get("timeOrigin") != before.get("timeOrigin") or (same_document and now.get("href") == url)\n            if moved and now.get("ready") in ("interactive", "complete"):\n                break\n            if time.monotonic() - started > NAVIGATE_SECONDS:\n                raise RuntimeError("Navigation did not settle; inspect the screen before continuing")\n            time.sleep(POLL_SECONDS)\n        page: dict[str, Any] = {}\n        left = NAVIGATE_SNAPSHOT_BY - (time.monotonic() - started)\n        if left > 0:\n            try:\n                page = self.snapshot(min(SETTLE_SECONDS, left))\n            except Exception:  # noqa: BLE001\n                page = {}\n            if time.monotonic() - started > NAVIGATE_SNAPSHOT_UNTIL:\n                page = {}\n        if not page:\n            url_result, title_result = self.ab.batch([["get", "url"], ["get", "title"]])\n            page = {"url": url_result.get("url"), "title": str(title_result.get("title") or "")[:200]}\n        return {"ok": True, **{key: page[key] for key in ("url", "title", "tree", "elements", "frameOrigins", "loading")\n                              if key in page}}\n\n    def save_pdf(self, tab: dict[str, Any]) -> None:\n        """Save the PDF the tab shows, if it shows one, with the call\'s downloads.\n\n        It is named after the tab\'s title, which the viewer takes from the PDF, unless that is only a\n        piece of its address, such as a blob: URL\'s id; the name is made safe as any download\'s is.\n        """\n        if not self.downloads:\n            return\n        title, url = str(tab.get("title") or "").strip(), str(tab.get("url") or "")\n        # The viewer titles a PDF without one by the last piece of its address, such as a blob: URL\'s id.\n        last = urlsplit(url).path.rstrip("/").rsplit("/", 1)[-1]\n        name = "" if not title or title in (last, unquote(last)) else download_name(title if title.lower().endswith(".pdf") else f"{title}.pdf")\n        with contextlib.suppress(Exception):\n            (saved,) = self.ab.batch([["eval", SAVE_PDF.replace("NAME", json.dumps(name))]], timeout=3.0)\n            if saved.get("result") is True:\n                # Waited for until its download begins, as a click on a download link is.\n                self.downloads.client.download_links.append(time.monotonic())\n\n    def dialog(self) -> dict[str, Any] | None:\n        """The JavaScript dialog (alert, confirm, prompt or beforeunload) the page has open, if any."""\n        try:\n            # Short: it can follow a step that already used most of the caller\'s time limit.\n            (status,) = self.ab.batch([["dialog", "status"]], timeout=3.0)\n        except Exception:  # noqa: BLE001\n            return None\n        return status if status.get("hasDialog") else None\n\n    def dialog_result(self, dialog: dict[str, Any], progress: dict[str, Any], remaining: bool = False) -> dict[str, Any]:\n        """An alert only informs and OK is its one answer, so it is closed and its message reported.\n        Any other dialog asks something: it stays open on the screen for computer_act or the person."""\n        kind = str(dialog.get("type") or "")\n        message = str(dialog.get("message") or "")[:300]\n        quoted = f": {json.dumps(message, ensure_ascii=False)}" if message else ""\n        if kind != "alert":\n            name = \'"Leave site?"\' if kind == "beforeunload" else kind\n            return {"ok": False, **progress, "error": f"A {name} dialog is open on the screen{quoted}",\n                    "dialog": kind, "fallback": "computer_act"}\n        note = f"The page showed an alert, now closed{quoted}."\n        try:\n            self.ab.batch([["dialog", "dismiss"]])\n            snap = self.snapshot(ACTION_WAIT_SECONDS)\n        except Exception:  # noqa: BLE001\n            return {"ok": False, **progress, "error": f"The page showed an alert{quoted}.", "fallback": "computer_act"}\n        # A step that was still running when the alert came may or may not have taken effect.\n        unsure = " Check whether the last step took effect." if progress.get("uncertain") else ""\n        if remaining or unsure:\n            after = " The remaining steps did not run." if remaining else ""\n            return {**snap, **progress, "ok": False, "error": f"{note}{unsure}{after}"}\n        return {**snap, **progress, "note": note}\n\n    def step(self, commands: list[list[str]]) -> list[Any]:\n        try:\n            results = self.ab.batch(commands)\n        except AbError as error:\n            if re.search(r"Element\\b.*\\bis disabled", str(error)):\n                raise Settled(DISABLED) from None\n            if any(marker in str(error) for marker in SETTLED_ERRORS):\n                raise Settled(str(error)) from None\n            raise\n        self.dialog_opened = any(result.get("dialogOpened") is True for result in results)\n        return results\n\n    def fill(self, ref: str, text: str) -> None:\n        _, kept = self.step([["fill", f"@{ref}", text], ["get", "value", f"@{ref}"]])\n        value = kept.get("value")\n        if isinstance(value, str) and value and value != text:\n            raise RuntimeError("Input did not accept the requested value")\n\n    def type(self, ref: str, text: str) -> None:\n        """Real key presses into whatever has focus, as a person types: a code widget that moves\n        focus from box to box gets each key in its own box. Before each key the page must still be\n        the same document, with focus in the field or a box next to it."""\n        token = os.urandom(8).hex()\n        _, start = self.step([["focus", f"@{ref}"], ["eval", TYPE_START.replace("TOKEN", token)\n                                                     .replace("WHOLE", json.dumps(len(text) > 1))]])\n        info = start.get("result") or {}\n        multiline = info.get("multiline") is True\n        # Enter in a one-line field would submit its form; Shift+Enter breaks the line elsewhere.\n        chars = [char for char in text.replace("\\r\\n", "\\n").replace("\\r", "\\n") if multiline or char != "\\n"]\n        check = ["eval", TYPE_CHECK.replace("TOKEN", token)]\n        commands: list[list[str]] = []\n        if info.get("frame") or len(chars) > CHECKED_KEYS:\n            for index, line in enumerate("".join(chars).split("\\n")):\n                if index:\n                    commands.append(["press", "Shift+Enter"])\n                if line:\n                    commands.append(["keyboard", "type", line])\n            keys_per_command = 0\n        else:\n            for char in chars:\n                commands += [check, key_command(char)]\n            keys_per_command = 2\n        try:\n            if commands:\n                self.ab.batch(commands, timeout=60.0)\n        except AbError as error:\n            if keys_per_command and error.index % keys_per_command == 0 and "Typing stopped" in str(error):\n                done, total = error.index // keys_per_command, len(chars)\n                if "Typing stopped: page" in str(error):\n                    raise TypingStopped(f"The page changed while typing, after {done} of {total} characters, "\n                                        "so the rest was not typed. Take a fresh snapshot before continuing.") from None\n                raise TypingStopped(f"Focus left the field while typing, after {done} of {total} characters, "\n                                    "so the rest was not typed. Check the page in this snapshot before trying again.") from None\n            raise\n        # A page that moved on after the last key, as auto-submitting codes do, has taken the step.\n        (done,) = self.ab.batch([["eval", TYPE_DONE.replace("TOKEN", token)\n                                  .replace("TEXT", json.dumps(text))]])\n        if (done.get("result") or {}).get("kept") is False:\n            raise KeysNotKept(NOT_KEPT)\n\n    def act(self, actions: list[dict[str, Any]]) -> dict[str, Any]:\n        validate_actions(actions)\n        completed = 0\n        uncertain = False\n        typed = False\n        try:\n            for step in actions:\n                kind, ref = step["kind"], step.get("ref")\n                node = self.control(ref, check_disabled=kind in ("fill", "type")) if ref is not None else None\n                typed = kind == "type" or (kind == "fill" and not (node and native_options(node)))\n                uncertain = True\n                if kind == "pay_token" or step.get("origin"):\n                    if ref is not None:\n                        self.step([["focus", f"@{ref}"]])\n                    page_secrets.run_step(self.port, self.target, step)\n                elif kind == "click":\n                    refused = purchase_refusal(step, *self.click_purchase(ref, node), completed)  # type: ignore[arg-type]\n                    if refused:\n                        return refused\n                    # agent-browser scrolls an element into view inside its frame, not the frame into view\n                    # on the page, so a click on a frame below the fold would land on whatever is there.\n                    frame = node.frame  # type: ignore[union-attr]\n                    # A native dropdown takes its option from fill; a click would open a list the page cannot see.\n                    if self.downloads:\n                        with contextlib.suppress(Exception):\n                            self.step([["focus", f"@{ref}"]])\n                            (link,) = self.ab.batch([["eval", "Boolean(document.activeElement?.closest(\'a[download]\'))"]])\n                            if link.get("result"):\n                                self.downloads.client.download_links.append(time.monotonic())\n                    self.step([*([["scrollintoview", f"@{frame.ref}"]] if frame else []),\n                               ["focus" if native_options(node) else "click", f"@{ref}"]])  # type: ignore[arg-type]\n                elif kind == "upload":\n                    self.step([["upload", f"@{ref}", *step["files"]]])\n                elif kind == "fill" and native_options(node):  # type: ignore[arg-type]\n                    self.step([["select", f"@{ref}", step["text"]]])\n                elif kind == "fill":\n                    self.fill(ref, step["text"])\n                else:\n                    try:\n                        self.type(ref, step["text"])\n                    except KeysNotKept:\n                        completed += 1\n                        raise\n                completed += 1\n                uncertain = False\n                dialog = self.dialog() if self.dialog_opened else None\n                if dialog:\n                    return self.dialog_result(dialog, {"completed": completed, "uncertain": False},\n                                              remaining=completed < len(actions))\n            started = time.monotonic()\n            quiet_from = time.time() + (TYPING_PAUSE_SECONDS if typed else 0.0)\n            busy = not self.settle(ACTION_WAIT_SECONDS, quiet_from=quiet_from)\n            left = ACTION_WAIT_SECONDS - (time.monotonic() - started)\n            snap = self.snapshot(0.0 if busy else max(0.0, left))\n            return {**snap, "completed": completed, **({"loading": True} if busy else {})}\n        except (Settled, TypingStopped, KeysNotKept) as exc:\n            # Nothing changed for this step, or typing stopped where it says. The page as it is goes with the reason.\n            try:\n                snap = self.snapshot(0.0)\n            except Exception:  # noqa: BLE001\n                snap = {}\n            error = NOT_KEPT if isinstance(exc, KeysNotKept) else str(exc)\n            return {"uncertain": False, **snap, "ok": False, "completed": completed, "error": error}\n        except Refused as exc:\n            # Settled, and fixable in the page browser: no desktop fallback.\n            return {"ok": False, "completed": completed, "uncertain": False, "error": str(exc)}\n        except CardFieldUncertain as exc:\n            return {"ok": False, "completed": completed, "uncertain": True, "error": str(exc)}\n        except TimeoutError:\n            return {"ok": False, "completed": completed, "uncertain": uncertain,\n                    "error": recovery.TIMEOUT_MESSAGE, "fallback": "computer_act"}\n        except Exception as exc:  # noqa: BLE001\n            dialog = self.dialog()\n            if dialog:\n                return self.dialog_result(dialog, {"completed": completed, "uncertain": uncertain},\n                                          remaining=completed + uncertain < len(actions))\n            return {"ok": False, "completed": completed, "uncertain": uncertain, "error": str(exc),\n                    "fallback": "computer_act"}\n\n\n# Typing runs in the page\'s own world: it reads and checks only what the page could change anyway.\n# A code is typed into its boxes: like-named one- or two-character inputs around the field, up to\n# where their numbering starts again, so a second code or a middle-initial field next to it is left alone.\nCODE_BOXES = r"""\n  // Boxes cap their own length at one or two characters. Number boxes ignore a cap, and some pages\n  // set none: those must be narrow and say they take one digit, so card or date fields never count.\n  const box = (input) => {\n    if (!(input instanceof HTMLInputElement)) return false;\n    if (input.maxLength > 0) return input.maxLength <= 2;\n    const width = input.getBoundingClientRect().width;\n    return ["text", "tel", "number", "password"].includes(input.type) && width > 0 && width <= 72\n      && (input.autocomplete === "one-time-code"\n        || (input.type === "number" && input.max !== "" && Number(input.max) <= 9));\n  };\n  const naming = (field) => [field.getAttribute("aria-label"), field.name, field.id,\n    ...Array.from(field.labels || [], (label) => label.textContent)].join("|").replace(/[\\d\\s]+/g, "").toLowerCase();\n  // Pages often label only the first box, with the prompt, and leave the rest unnamed. Unnamed boxes\n  // straight after a named one, with no other field between, are its code, if the whole run is a code\'s size.\n  const unnamed = (field) => /^\\|*$/.test(naming(field));\n  const cache = new WeakMap();\n  const led = new WeakMap();\n  const named = (field, container) => {\n    let names = cache.get(container);\n    if (!names) {\n      names = new Map();\n      const members = new Set();\n      led.set(container, members);\n      const inputs = [...container.querySelectorAll("input")].filter((input) => input.type !== "hidden");\n      const bare = (input) => input && box(input) && unnamed(input);\n      inputs.forEach((input, at) => {\n        if (names.has(input)) return;\n        names.set(input, naming(input));\n        if (!bare(input)) return;\n        let from = at;\n        let to = at;\n        while (bare(inputs[from - 1])) from--;\n        while (bare(inputs[to + 1])) to++;\n        const lead = inputs[from - 1];\n        const name = lead && box(lead) && to - from >= 2 && to - from <= 6 ? naming(lead) : naming(input);\n        if (name === naming(input)) return;\n        for (let i = from - 1; i <= to; i++) members.add(inputs[i]);\n        for (let i = from; i <= to; i++) names.set(inputs[i], name);\n      });\n      cache.set(container, names);\n    }\n    return names.get(field) ?? naming(field);\n  };\n  // Boxes with no length cap only count as a code when a named box leads them.\n  const joined = (input, container) => input.maxLength > 0 || (named(input, container), led.get(container).has(input));\n  const numberOf = (field) => {\n    const found = /\\d+/.exec(field.getAttribute("aria-label")\n      || Array.from(field.labels || [], (label) => label.textContent).join(" ") || field.name || "");\n    return found ? Number(found[0]) : null;\n  };\n  const like = (container, name) => [...container.querySelectorAll("input")].filter((input) => box(input)\n    && joined(input, container) && named(input, container) === name);\n  function codeOf(el) {\n    if (!box(el)) return null;\n    for (let node = el.parentElement, up = 0; node && up < 3; node = node.parentElement, up++) {\n      if ([...node.querySelectorAll("input")].filter(box).length < 4 || !joined(el, node)) continue;\n      const boxes = like(node, named(el, node));\n      const restarts = (a, b) => numberOf(a) !== null && numberOf(b) !== null && numberOf(b) <= numberOf(a);\n      let from = boxes.indexOf(el);\n      let to = from;\n      while (from > 0 && !restarts(boxes[from - 1], boxes[from])) from--;\n      while (to < boxes.length - 1 && !restarts(boxes[to], boxes[to + 1])) to++;\n      return { container: node, name: named(el, node), from, size: to - from + 1, at: boxes.indexOf(el) };\n    }\n    return null;\n  }\n  const empty = (field) => {\n    Object.getOwnPropertyDescriptor(Object.getPrototypeOf(field), "value").set.call(field, "");\n    field.dispatchEvent(new Event("input", { bubbles: true }));\n  };\n  const focused = () => {\n    let active = document.activeElement;\n    while (active?.shadowRoot?.activeElement) active = active.shadowRoot.activeElement;\n    return active;\n  };\n"""\n\nTYPE_START = "(() => {" + CODE_BOXES + r"""\n  const el = focused();\n  if (el instanceof HTMLIFrameElement || el instanceof HTMLFrameElement) return { frame: true };\n  if (!el || el === document.body) throw new Error("The field did not take keyboard focus. Click it, then type again.");\n  const code = codeOf(el);\n  let start = code ? code.at : 0;\n  if (code && code.size > 1 && WHOLE) {\n    // A whole code replaces the code: every box is emptied and typing starts at the first. Widgets\n    // that draw their boxes again on each input are found again in the same place each time.\n    const boxes = () => {\n      cache.delete(code.container);\n      return like(code.container, code.name).slice(code.from, code.from + code.size);\n    };\n    for (let i = 0; i < 24; i++) {\n      const filled = boxes().find((field) => field.value);\n      if (!filled) break;\n      empty(filled);\n    }\n    start = code.from;\n    boxes()[0]?.focus();\n  } else if (el.isContentEditable) {\n    const range = document.createRange();\n    range.selectNodeContents(el);\n    getSelection().removeAllRanges();\n    getSelection().addRange(range);\n  } else if ((el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) && el.value) {\n    empty(el);\n  }\n  window.__rakazoTyping = { token: "TOKEN", el, code, start };\n  return { multiline: !(el instanceof HTMLInputElement) };\n})()"""\n\n# Focus may move on by itself to the next box of the code, and nowhere else.\nTYPE_CHECK = "(() => {" + CODE_BOXES + r"""\n  const typing = window.__rakazoTyping;\n  if (typing?.token !== "TOKEN") throw new Error("Typing stopped: page");\n  const active = focused();\n  const { el, code } = typing;\n  const holds = active === el || el.contains(active) || (code !== null && code.container.isConnected\n    && code.container.contains(active) && box(active) && named(active, code.container) === code.name);\n  if (!holds) throw new Error("Typing stopped: focus");\n  return true;\n})()"""\n\nTYPE_DONE = "(() => {" + CODE_BOXES + r"""\n  const typing = window.__rakazoTyping;\n  if (typing?.token !== "TOKEN") return { kept: true };\n  const { el, code, start } = typing;\n  const letters = (value) => String(value).replace(/[^\\p{L}\\p{N}]/gu, "").toLowerCase();\n  const wanted = letters(TEXT);\n  if (code) {\n    if (!code.container.isConnected) return { kept: true };\n    const shown = like(code.container, code.name).slice(start).map((field) => field.value).join("");\n    return { kept: letters(shown).slice(0, wanted.length) === wanted };\n  }\n  if (!el.isConnected) return { kept: true };\n  return { kept: letters(el.isContentEditable ? el.innerText : el.value) === wanted };\n})()"""\n\n\ndef key_command(char: str) -> list[str]:\n    """One character as a real key press, or as inserted text where a key cannot name it."""\n    if char == "\\n":\n        return ["press", "Shift+Enter"]\n    if char.isascii() and char.isalnum():\n        return ["press", char]\n    return ["keyboard", "inserttext", char]\n\n\nclass CdpClient(page_secrets.CdpClient):\n    """The shared CDP transport with events for this call\'s downloads and its page\'s load."""\n\n    def __init__(self, ws_url: str) -> None:\n        super().__init__(ws_url)\n        # The load milestones each document has reached, by frame and document.\n        self.lifecycle: dict[tuple[Any, Any], set[str]] = {}\n        # Downloads Chromium began since download events were turned on, by guid, in the order they began.\n        self.downloads: dict[str, dict[str, Any]] = {}\n        # The MIME type each document response was sent with, by URL, for the type of a download.\n        self._mime_types: dict[str, str] = {}\n        # The page\'s top frame while its downloads are saved, and the documents it requested since then\n        # that have not loaded: when each was requested and when its answer came. A download\'s answer\n        # ends its request just before the download begins.\n        self.download_frame: str | None = None\n        self._documents: dict[str, list[float | None]] = {}\n        # When the bot clicked links that download (`<a download>`) whose downloads have not begun: the\n        # browser makes their requests, so the page has no document for them.\n        self.download_links: list[float] = []\n\n    def _handle_event(self, message: dict[str, Any]) -> None:\n        super()._handle_event(message)\n        method = message.get("method")\n        params = message.get("params") or {}\n        if method == "Browser.downloadWillBegin":\n            if self.download_links:\n                self.download_links.pop(0)\n            guid = params.get("guid")\n            if isinstance(guid, str):\n                self.downloads.setdefault(guid, {"name": params.get("suggestedFilename"), "url": params.get("url"),\n                                                 "state": "inProgress", "received": 0, "total": 0})\n        elif method == "Page.lifecycleEvent":\n            self.lifecycle.setdefault((params.get("frameId"), params.get("loaderId")), set()).add(str(params.get("name")))\n        elif method == "Browser.downloadProgress":\n            download = self.downloads.get(params.get("guid"))\n            if download is not None:\n                download.update(state=params.get("state"), received=params.get("receivedBytes") or 0,\n                                total=params.get("totalBytes") or 0)\n        elif method == "Network.responseReceived":\n            response = params.get("response") or {}\n            if params.get("type") == "Document" and isinstance(response.get("mimeType"), str):\n                self._mime_types[str(response.get("url"))] = response["mimeType"]\n            if params.get("requestId") in self._documents:\n                self._documents[params["requestId"]][1] = time.monotonic()\n        elif method == "Network.requestWillBeSent":\n            request_id = params.get("requestId")\n            if (self.download_frame and params.get("frameId") == self.download_frame\n                    and params.get("type") == "Document" and isinstance(request_id, str)):\n                self._documents.setdefault(request_id, [time.monotonic(), None])\n        elif method in ("Network.loadingFinished", "Network.loadingFailed"):\n            if method == "Network.loadingFinished":\n                self._documents.pop(params.get("requestId"), None)\n            elif params.get("requestId") in self._documents:\n                self._documents[params["requestId"]][1] = time.monotonic()\n\n    def mime_type(self, url: Any) -> str | None:\n        kind = self._mime_types.get(str(url), "")\n        # A server\'s text that reaches the bot, so only a plain type/subtype is kept.\n        return kind if len(kind) <= 100 and re.fullmatch(r"[\\w.+-]+/[\\w.+-]+", kind, re.ASCII) else None\n\n    def documents_pending(self, grace: float, wait: float) -> bool:\n        """Whether a document the page requested may still turn out to be a download."""\n        now = time.monotonic()\n        return any(now - clicked < wait for clicked in self.download_links) or any(\n            now - requested < wait if answered is None else now - answered < grace\n            for requested, answered in self._documents.values())\n\n    def listen(self, seconds: float) -> None:\n        """Handle the events that arrive within `seconds`, as they arrive, so their times are true."""\n        assert self._sock is not None\n        deadline = time.monotonic() + seconds\n        while (left := deadline - time.monotonic()) > 0:\n            self._sock.settimeout(left)\n            try:\n                frame = self._read_frame()\n            except socket.timeout:\n                return\n            message = json.loads(frame.decode("utf-8"))\n            if isinstance(message, dict) and message.get("method"):\n                self._handle_event(message)\n\n\nclass PageLoad:\n    """Chromium\'s own record of the page\'s load, which covers requests made before agent-browser attached."""\n\n    def __init__(self, port: int, target: str) -> None:\n        self.client: CdpClient | None = None\n        self.session: str | None = None\n        try:\n            self.client = CdpClient(discover_ws_url(port))\n            self.client.connect()\n            self.session = self.client.call("Target.attachToTarget", {"targetId": target, "flatten": True},\n                                            timeout_s=2.0)["sessionId"]\n            self.client.call("Page.enable", session_id=self.session, timeout_s=2.0)\n            # Enabling lifecycle events replays the ones the current document has already reached.\n            self.client.call("Page.setLifecycleEventsEnabled", {"enabled": True}, session_id=self.session, timeout_s=2.0)\n        except Exception:  # noqa: BLE001\n            self.session = None\n\n    def idle(self) -> bool:\n        """Whether the page has loaded and Chromium has seen no request for 500 ms (its networkIdle).\n\n        A browser that cannot say leaves the wait to agent-browser\'s log.\n        """\n        if self.client is None or self.session is None:\n            return True\n        try:\n            frame = self.client.call("Page.getFrameTree", session_id=self.session, timeout_s=2.0)["frameTree"]["frame"]\n        except Exception:  # noqa: BLE001\n            return True\n        return {"load", "networkIdle"} <= self.client.lifecycle.get((frame.get("id"), frame.get("loaderId")), set())\n\n    def close(self) -> None:\n        if self.client:\n            self.client.close()\n\n\ndef max_file_bytes() -> int:\n    """The most bytes a file moved between this computer and a page may have, uploaded or downloaded."""\n    try:\n        override = int(os.environ.get("RAKAZO_BROWSER_UPLOAD_MAX_BYTES", ""))\n    except ValueError:\n        return MAX_UPLOAD_BYTES\n    return override if override > 0 else MAX_UPLOAD_BYTES\n\n\n# A navigate or act that the host gives the bot\'s download folder saves the files its page downloads\n# there, under the name the site gave (made safe), and lists them in its result.\nMAX_DOWNLOADS = MAX_UPLOAD_FILES\n# Downloads are waited for until this long after the helper started, inside the supervisor\'s limit on\n# one call. One still running then is listed as downloading and given its name when it finishes.\nDOWNLOAD_WAIT_UNTIL = 15.0\n# A document whose answer is a download ends its request a moment before the download begins. A\n# document still unanswered this long after it was requested is a slow page, not waited for longer.\nDOWNLOAD_BEGIN_SECONDS = 0.5\nDOCUMENT_WAIT_SECONDS = 5.0\nFINISH_LATER_SECONDS = 15 * 60\nSTARTED = time.monotonic()\nDOWNLOAD_FAILED = "The download failed."\nDOWNLOADS_UNUSABLE = "Downloads cannot be saved on this computer: its Downloads folder is not usable."\nTOO_MANY_DOWNLOADS = f"downloads not saved: a call saves at most {MAX_DOWNLOADS} files."\n\n\ndef download_folder(folder: Any, home: str) -> str:\n    """The bot\'s download folder, made inside the home folder without passing through a symlink.\n\n    A folder reached through a symlink (bots/b1 -> bots/b2) could put files in another bot\'s folder.\n    """\n    if not isinstance(folder, str) or not folder or "\\0" in folder or os.path.isabs(folder):\n        raise RuntimeError(DOWNLOADS_UNUSABLE)\n    expected = os.path.normpath(os.path.join(home, folder))\n    if expected == home or os.path.commonpath([home, expected]) != home:\n        raise RuntimeError(DOWNLOADS_UNUSABLE)\n    path = home\n    for part in os.path.relpath(expected, home).split(os.sep):\n        path = os.path.join(path, part)\n        with contextlib.suppress(FileExistsError):\n            os.mkdir(path, 0o755)\n        if os.path.islink(path) or not os.path.isdir(path):\n            raise RuntimeError(DOWNLOADS_UNUSABLE)\n    return expected\n\n\ndef download_name(name: Any) -> str:\n    """A site\'s name for a file as one short, plain path segment: it is untrusted text the bot reads and\n    puts in its shell, so shell characters such as `$`, backticks, quotes and `;` become `_` too."""\n    text = "".join(\n        "_" if char in "/\\\\$`;|&<>!\\"\'" else " " if unicodedata.category(char)[0] in "CZ" else char\n        for char in unicodedata.normalize("NFC", str(name or ""))\n    )\n    stem, ext = os.path.splitext(" ".join(text.split()).strip(". "))\n    if len(ext) > 12 or " " in ext:\n        stem, ext = stem + ext, ""\n    while stem and (len(stem) + len(ext) > 80 or len((stem + ext).encode()) > 200):\n        stem = stem[:-1]\n    stem = stem.rstrip(". ")\n    return stem + ext if stem else "download" + ext\n\n\ndef free_name(folder: str, name: str, taken: set[str]) -> str:\n    """`name`, or `name (1)` and so on, that nothing in the folder or `taken` already has."""\n    stem, ext = os.path.splitext(name)\n    for number in range(1000):\n        candidate = name if number == 0 else f"{stem} ({number}){ext}"\n        if candidate not in taken and not os.path.lexists(os.path.join(folder, candidate)):\n            return candidate\n    raise RuntimeError(DOWNLOAD_FAILED)\n\n\ndef place_download(staged: str, folder: str, name: str, taken: set[str]) -> str:\n    """Give a finished download its name. A link never replaces an existing entry or writes through a symlink."""\n    info = os.lstat(staged)\n    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size > max_file_bytes():\n        raise RuntimeError(DOWNLOAD_FAILED)\n    while True:\n        chosen = free_name(folder, name, taken)\n        try:\n            os.link(staged, os.path.join(folder, chosen))\n        except FileExistsError:\n            taken.add(chosen)\n            continue\n        os.unlink(staged)\n        return chosen\n\n\ndef remove_partial(staged: str) -> None:\n    for path in (staged, staged + ".crdownload"):\n        with contextlib.suppress(OSError):\n            os.unlink(path)\n\n\nclass Downloads:\n    """Saves the files a call\'s page downloads into the bot\'s folder, from when it is made until `finish`.\n\n    Chromium\'s download setting covers the whole browser and goes back to its default when the CDP\n    connection that made it closes, so the person\'s own downloads afterwards are unaffected.\n    """\n\n    def __init__(self, client: CdpClient, folder: Any, session_id: str | None = None, home: str | None = None) -> None:\n        self.client = client\n        self.home = os.path.realpath(home or os.environ.get("HOME") or "/home/rakazo")\n        try:\n            self.folder: str | None = download_folder(folder, self.home)\n        except (RuntimeError, OSError):\n            # Fail closed: the call\'s downloads are refused rather than saved anywhere else.\n            self.folder = None\n        try:\n            client.call("Browser.setDownloadBehavior", {\n                "behavior": "allowAndName" if self.folder else "deny",\n                **({"downloadPath": self.folder} if self.folder else {}),\n                "eventsEnabled": True,\n            })\n        except Exception:  # noqa: BLE001\n            # A browser that cannot be told downloads as it would without a folder; the call goes on.\n            self.folder = None\n        self.max_bytes = max_file_bytes()\n        self.stopped: dict[str, str] = {}\n        # Only the page\'s own navigations can turn into downloads; a frame\'s slow document is not waited for.\n        with contextlib.suppress(Exception):\n            if session_id:\n                frame = client.call("Page.getFrameTree", session_id=session_id)["frameTree"]["frame"]\n                client.download_frame = frame["id"]\n\n    def check_limits(self) -> None:\n        """Cancel a download past the call\'s count or over the size limit; Chromium deletes what it wrote."""\n        for index, (guid, download) in enumerate(self.client.downloads.items()):\n            if guid in self.stopped or download["state"] not in ("inProgress", "completed"):\n                continue\n            if index >= MAX_DOWNLOADS:\n                self.stopped[guid] = TOO_MANY_DOWNLOADS\n            elif max(download["total"], download["received"]) > self.max_bytes:\n                self.stopped[guid] = f"Not saved: larger than {self.max_bytes / (1024 * 1024):g} MB."\n            else:\n                continue\n            with contextlib.suppress(Exception):\n                self.client.call("Browser.cancelDownload", {"guid": guid})\n\n    def finish(self) -> list[dict[str, Any]]:\n        """Wait for the call\'s downloads within its time, then list each one as the bot will find it."""\n        while True:\n            self.check_limits()\n            running = any(download["state"] == "inProgress" and guid not in self.stopped\n                          for guid, download in self.client.downloads.items())\n            left = STARTED + DOWNLOAD_WAIT_UNTIL - time.monotonic()\n            documents = self.client.documents_pending(DOWNLOAD_BEGIN_SECONDS, DOCUMENT_WAIT_SECONDS)\n            if left <= 0 or not (running or documents):\n                break\n            self.client.listen(min(0.05, left))\n        taken: set[str] = set()\n        later: list[dict[str, str]] = []\n        found = [self.entry(guid, download, taken, later) for guid, download in self.client.downloads.items()]\n        if later:\n            # Detached and holding none of this call\'s files or connections, so the call ends now. Each\n            # call that leaves a download running starts one; it ends with them or after FINISH_LATER_SECONDS.\n            env = {key: value for key, value in os.environ.items()\n                   if key not in ("RAKAZO_BROWSER_ARGS_STDIN", "RAKAZO_BROWSER_WATCH_STDIN")}\n            subprocess.Popen([sys.executable, os.path.abspath(__file__), "finish", json.dumps({"downloads": later})],\n                             stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\n                             start_new_session=True, close_fds=True, env=env)\n        if len(found) > MAX_DOWNLOADS:\n            found = found[:MAX_DOWNLOADS] + [{"error": f"{len(found) - MAX_DOWNLOADS} more {TOO_MANY_DOWNLOADS}"}]\n        return found\n\n    def entry(self, guid: str, download: dict[str, Any], taken: set[str],\n              later: list[dict[str, str]]) -> dict[str, Any]:\n        name = download_name(download["name"])\n        if self.folder is None:\n            return {"name": name, "error": DOWNLOADS_UNUSABLE}\n        staged = os.path.join(self.folder, guid)\n        if guid in self.stopped or download["state"] not in ("completed", "inProgress"):\n            remove_partial(staged)\n            return {"name": name, "error": self.stopped.get(guid, DOWNLOAD_FAILED)}\n        shown = os.path.relpath(self.folder, self.home)\n        if download["state"] == "inProgress":\n            # Not held on disk until it finishes: a file given this name meanwhile makes it `name (1)`.\n            name = free_name(self.folder, name, taken)\n            taken.add(name)\n            later.append({"guid": guid, "staged": staged, "folder": self.folder, "name": name})\n            return {"name": name, "path": f"{shown}/{name}", "state": "downloading", "size": download["received"]}\n        try:\n            name = place_download(staged, self.folder, name, taken)\n            size = os.stat(os.path.join(self.folder, name)).st_size\n        except (OSError, RuntimeError):\n            remove_partial(staged)\n            return {"name": name, "error": DOWNLOAD_FAILED}\n        taken.add(name)\n        kind = self.client.mime_type(download["url"]) or mimetypes.guess_type(name)[0]\n        return {"name": name, "path": f"{shown}/{name}", "size": size, **({"type": kind} if kind else {})}\n\n\ndef finish_later(pending: list[dict[str, str]], seconds: float = FINISH_LATER_SECONDS) -> None:\n    """Name the downloads still running when their call ended once Chromium finishes them.\n\n    Chromium writes `<guid>.crdownload` and renames it `<guid>` when complete. Over the size limit,\n    the download is cancelled.\n    """\n    until = time.monotonic() + seconds\n    max_bytes = max_file_bytes()\n    begun: set[str] = set()\n    placement_failed: set[str] = set()\n    while pending and time.monotonic() < until:\n        time.sleep(0.5)\n        for item in list(pending):\n            staged = item["staged"]\n            try:\n                size = os.path.getsize(staged + ".crdownload")\n            except OSError:\n                if os.path.exists(staged):\n                    try:\n                        place_download(staged, item["folder"], item["name"], set())\n                    except (OSError, RuntimeError):\n                        placement_failed.add(staged)\n                    else:\n                        pending.remove(item)\n                        placement_failed.discard(staged)\n                elif staged in begun:\n                    # Cancelled or failed: Chromium removed what it wrote.\n                    pending.remove(item)\n                continue\n            begun.add(staged)\n            if size > max_bytes:\n                pending.remove(item)\n                with contextlib.suppress(Exception):\n                    client = CdpClient(discover_ws_url(cdp_port()))\n                    client.connect()\n                    try:\n                        client.call("Browser.cancelDownload", {"guid": item["guid"]})\n                    finally:\n                        client.close()\n                remove_partial(staged)\n\n    if any(item["staged"] in placement_failed for item in pending):\n        # Keep completed files available for retries until the deadline, then fail like entry().\n        for item in pending:\n            if item["staged"] in placement_failed:\n                remove_partial(item["staged"])\n        raise RuntimeError(DOWNLOAD_FAILED)\n\n\n# -- purchases ----------------------------------------------------------------------------------------\n\nPURCHASE_CHANGED = ("The page changed since the user approved this purchase, so the click was not made. "\n                    "Call browser_act again with only this click; that asks the user again.")\nPURCHASE_REFUSED = ("This click would complete a purchase, so the user must approve it. "\n                    "Call browser_act again with only this click; that asks the user.")\n\n# The click that pays, books or orders is the one the user must approve. Read in page_secrets\' isolated\n# world, so the page cannot hide a button or fake an approval; it can only word its own text.\nPURCHASE_HELPERS = r"""\n(() => {\n  if (window.__rakazoPurchase) return true;\n  function visible(el) {\n    if (!(el instanceof Element)) return false;\n    const style = window.getComputedStyle(el);\n    if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0") return false;\n    const rect = el.getBoundingClientRect();\n    return rect.width > 0 && rect.height > 0;\n  }\n  const clean = (text) => String(text).replace(/\\s+/g, " ").trim();\n  // What a click at (x, y) reaches, looking into shadow trees.\n  function elementAtPoint(x, y) {\n    let hit = document.elementFromPoint(x, y);\n    while (hit?.shadowRoot && typeof hit.shadowRoot.elementFromPoint === "function") {\n      const inner = hit.shadowRoot.elementFromPoint(x, y);\n      if (!inner || inner === hit) break;\n      hit = inner;\n    }\n    return hit;\n  }\n  const CONTROL_ROLES = ["button", "link", "textbox", "checkbox", "radio", "menuitem", "menuitemcheckbox",\n    "menuitemradio", "tab", "option", "switch", "combobox", "treeitem"];\n  function isInteractive(el) {\n    const tag = el.tagName.toLowerCase();\n    if (["a", "button", "input", "textarea", "select", "summary"].includes(tag)) return true;\n    if (el.isContentEditable || CONTROL_ROLES.includes(el.getAttribute("role"))) return true;\n    if (el.hasAttribute("onclick") || Number(el.getAttribute("tabindex") ?? NaN) >= 0) return true;\n    // Only the outermost element styled as clickable counts: its children inherit the pointer.\n    return window.getComputedStyle(el).cursor === "pointer"\n      && (!el.parentElement || window.getComputedStyle(el.parentElement).cursor !== "pointer");\n  }\n  const SURROUNDINGS = "header, nav, footer, aside, [role=banner], [role=navigation], [role=contentinfo], [role=complementary]";\n  const NOTICE = /cookie|consent|gdpr|onetrust/i;\n  const CARD_TOKENS = ["cc-number", "cc-csc", "cc-exp", "cc-exp-month", "cc-exp-year"];\n  const CARD_NAMING = /card[\\s_-]*(?:number|no\\b|num\\b)|cardnumber|cc[\\s_-]*(?:num|number)|ccnum|(?<![a-z])(?:cvv2?|cvc2?|csc)(?![a-z])|card[\\s_-]*(?:security|verification)|(?:^|[^\\d•*x])(?:\\d|•|\\*|x){4}[\\s-]+(?:\\d|•|\\*|x){4}[\\s-]+(?:\\d|•|\\*|x){4}|מספר[\\s_-]*כרטיס|כרטיס[\\s_-]*אשראי/i;\n  // A gift card, voucher or coupon number is not the card that pays.\n  const NOT_A_CARD = /gift|voucher|coupon|promo|loyalty|rewards?\\b|שובר|קופון|מתנה|הטבה/i;\n  function cardLike(el) {\n    if (!(el instanceof HTMLInputElement) || !["text", "tel", "number", "password"].includes(el.type) || !visible(el)) return false;\n    const tokens = (el.getAttribute("autocomplete") || "").toLowerCase().split(/\\s+/);\n    if (CARD_TOKENS.some((token) => tokens.includes(token))) return true;\n    const naming = [el.name, el.id, el.placeholder, el.getAttribute("aria-label"),\n      ...Array.from(el.labels || [], (label) => label.textContent)].join(" ");\n    return CARD_NAMING.test(naming) && !NOT_A_CARD.test(naming);\n  }\n  // Inputs of the page and of its open shadow trees, where some checkouts draw their card fields.\n  function deepInputs(root = document, found = []) {\n    for (const el of root.querySelectorAll("*")) {\n      if (el instanceof HTMLInputElement) found.push(el);\n      if (el.shadowRoot && found.length < 2000) deepInputs(el.shadowRoot, found);\n    }\n    return found;\n  }\n  const pageCards = () => deepInputs().filter(cardLike);\n  // What the control says, in each way it can say it: its own text or value, its aria label, its title.\n  // Direction marks and no-break spaces read as spaces; zero-width characters, which split a word without\n  // showing, are dropped.\n  const tidy = (text) => clean(String(text ?? "").replace(/[‎‏‪-‮ ]/g, " ")\n    .replace(/[\\u200B-\\u200D\\u2060-\\u2064\\uFEFF]/g, ""));\n  function wordsOf(el) {\n    const root = el.getRootNode();\n    const named = (el.getAttribute("aria-labelledby") || "").trim().split(/\\s+/).filter(Boolean)\n      .map((id) => root.getElementById?.(id)?.textContent || "").join(" ");\n    return [el instanceof HTMLInputElement ? el.value || el.getAttribute("alt") : el.innerText || el.textContent,\n      named, el.getAttribute("aria-label"), el.getAttribute("title")].map(tidy).filter(Boolean);\n  }\n  // A phrase compares without its case, outer punctuation or icons.\n  const phrase = (text) => text.toLowerCase().replace(/^[^\\p{L}\\p{N}$€£₪¥]+|[^\\p{L}\\p{N})]+$/gu, "");\n  const CURRENCY = "[$€£₪¥]|usd|eur|gbp|ils|nis";\n  const SPENDS = `${CURRENCY}|\\\\d`;\n  // The last step of an order. Each starts the phrase, so "to checkout", "continue to payment", "add to\n  // cart", "pay later" and a lone "confirm" or "continue" are not final steps.\n  const FINAL_STEP = [\n    new RegExp(`^(?:pay(?: securely)?(?: now)?|pay now securely|pay (?:with|using|by|via) .+|pay (?:${SPENDS}).*)$`),\n    /^make (?:a |the |my )?payment\\b/,\n    new RegExp(`^send (?:money|payment|funds|(?:${CURRENCY})\\\\s?\\\\d.*)`),\n    /^confirm (?:the |your |my )?(?:transfer|payment|bid|purchase)\\b/,\n    /^commit to buy\\b/,\n    /^request to book\\b/,\n    /^place (?:a |the |your |my )?bid\\b/,\n    // "Buy", "Buy now", "Buy it", "Buy this", "Buy $5"; not "Buy gift cards".\n    new RegExp(`^buy(?: now| it| this| it now)?$|^buy (?:${SPENDS})`),\n    /^purchase\\b(?! (?:history|orders?|details|options|agreement|terms))/,\n    /^place (?:your |my |the )?order\\b/,\n    /^(?:complete|finish|finalize|confirm|submit|review and place) (?:your |my |the )?(?:order|purchase|booking|reservation|payment|checkout)\\b/,\n    /^(?:confirm|agree|accept|authori[sz]e) (?:and|&) (?:pay|book|purchase|order)\\b/,\n    /^authori[sz]e payment\\b/,\n    /^(?:book|order|reserve) and pay\\b/,\n    // "Book now" and "Order now" often only open a checkout: a final step when the label has an amount.\n    new RegExp(`^(?:book|order|reserve) now\\\\b.*(?:${SPENDS})`),\n    new RegExp(`^(?:subscribe|donate|upgrade|start (?:my )?(?:free )?(?:trial|subscription)).*(?:${SPENDS})`),\n    /^(?:שלם|שלמו|תשלום עכשיו|אישור (?:והזמנה|הזמנה|תשלום|רכישה|ותשלום)|ביצוע (?:הזמנה|תשלום|רכישה)|קנה|קנו|רכוש|רכשו)(?:\\s|$)/,\n    // "הזמן" and "להזמנה" also open a booking page or a meeting: a final step with an amount.\n    new RegExp(`^(?:הזמן|הזמינו|להזמנה)(?:\\\\s|$).*(?:${SPENDS})`),\n  ];\n  // "Pay bill", "Pay invoice": a final step only for a control that submits a form or sits in a card form,\n  // so a plan toggle such as "Pay monthly" asks nothing.\n  const PAY_WORD = /^pay (?!later\\b|in\\b|over\\b|with\\b)\\S+$/;\n  function submittedForm(el) {\n    if (el instanceof HTMLButtonElement) return el.type === "submit" ? el.form : null;\n    if (el instanceof HTMLInputElement) return ["submit", "image"].includes(el.type) ? el.form : null;\n    return null;\n  }\n  const inPaymentForm = (el) => {\n    const form = el.form || el.closest("form");\n    return Boolean(form) && (submittedForm(el) !== null || [...form.elements].some(cardLike));\n  };\n  const isFinalStep = (words, el) => words.some((word) => FINAL_STEP.some((pattern) => pattern.test(phrase(word)))\n    || (el && PAY_WORD.test(phrase(word)) && inPaymentForm(el)));\n  // Controls on a payment page that never pay.\n  const NOT_PAYING = /^(?:back|go back|previous|cancel|edit|change|remove|delete|clear|apply|redeem|coupon|promo|discount|gift card|show|hide|help|close|dismiss|terms|privacy|learn more|view|select (?:a )?seat|choose (?:a )?seat|sign in|log in|login|sign up|register|forgot|add (?:a )?(?:promo|coupon|code|gift|note)|add to (?:cart|basket|bag))\\b|^(?:חזרה|ביטול|עריכה|שינוי|הסרה|קופון|סגירה|סגור|עזרה|תנאי|פרטיות|התחבר|כניסה|החל|הוסף לסל|הוספה לסל)(?:\\s|$)/;\n  // A number may group its thousands with spaces, as in "1 234,56 €".\n  const NUMBER = "\\\\d(?:[\\\\d.,]|[ \\\\u00a0\\\\u202f](?=\\\\d{3}))*";\n  const MONEY = new RegExp(`(?:[$€£₪¥]\\\\s?${NUMBER}|${NUMBER}\\\\s?(?:[$€£₪¥]|USD|EUR|GBP|ILS|NIS|ש"ח|ש״ח)|(?:USD|EUR|GBP|ILS|NIS)\\\\s?${NUMBER})`, "gi");\n  const TOTAL = /(?<!sub)total|amount due|balance due|to pay|you pay|סה[״"\'׳]?כ|סך[\\s-]*הכל|לתשלום/i;\n  const moneyIn = (text, last) => {\n    const found = String(text).match(MONEY);\n    return found ? found[last ? found.length - 1 : 0].replace(/[.,\\s]+$/, "").slice(0, 40) : "";\n  };\n  // The amount the page shows next to its total, the last one when it shows several.\n  function totalShown() {\n    const lines = String(document.body?.innerText || "").split("\\n").slice(0, 400);\n    let found = "";\n    lines.forEach((line, i) => {\n      if (!TOTAL.test(line.slice(0, 200))) return;\n      found = moneyIn(line.slice(0, 200), true) || moneyIn(lines[i + 1] || "", false) || found;\n    });\n    return found;\n  }\n  // Cookie notices and site menus come around every page; they are not the checkout.\n  function inSurroundings(el) {\n    if (el.closest(SURROUNDINGS) && !el.closest("main, [role=main], form")) return true;\n    for (let node = el; node && node !== document.body; node = node.parentElement) {\n      if (NOTICE.test(`${node.id} ${typeof node.className === "string" ? node.className : ""}`)) return true;\n    }\n    return false;\n  }\n  const isPlainLink = (el) => el.tagName.toLowerCase() === "a" && el.getAttribute("role") !== "button"\n    && !el.hasAttribute("onclick") && !["", "#"].includes((el.getAttribute("href") || "").trim())\n    && !/^javascript:/i.test(el.getAttribute("href") || "");\n  // A control that presses something, as opposed to a field, a choice or a link to another page.\n  function pressable(el) {\n    const tag = el.tagName.toLowerCase();\n    if (tag === "button") return true;\n    if (tag === "input") return ["submit", "button", "image"].includes(el.type);\n    if (["select", "textarea", "summary", "label"].includes(tag) || el.isContentEditable) return false;\n    if (tag === "a") return !isPlainLink(el);\n    const role = el.getAttribute("role");\n    return role === "button" || (!role && isInteractive(el));\n  }\n  // Page text is cut by characters, not code units, so a cut never leaves half an emoji.\n  const cut = (text, max) => Array.from(text).slice(0, max).join("");\n  // What the card shows: the button\'s text, and the amount the button names or else the page\'s total.\n  // `words`: everything the control says, so an amount only its aria label names is the one shown.\n  function shownPurchase(reason, label, words = [label]) {\n    const named = words.map((word) => moneyIn(word, false)).find(Boolean) || "";\n    return { reason, label: cut(label, 80), amount: named || totalShown(), amountFrom: named ? "button" : "page" };\n  }\n  // `frame`: the page shows a payment provider\'s card frame, which only the caller can vouch for.\n  function purchaseOf(el, frame) {\n    const words = wordsOf(el);\n    const form = submittedForm(el);\n    let reason = null;\n    if (form && ([...form.elements].some(cardLike) || (frame && form.querySelector("iframe,frame")))) reason = "card_form";\n    else if ((el instanceof HTMLButtonElement || el instanceof HTMLInputElement || el instanceof HTMLAnchorElement\n        || el.getAttribute("role") === "button" || pressable(el)) && isFinalStep(words, el)) reason = "final_step";\n    else if ((frame || pageCards().length) && pressable(el) && !inSurroundings(el)\n        && !words.some((word) => NOT_PAYING.test(phrase(word)))) reason = "payment_page";\n    return reason ? shownPurchase(reason, words[0] || "", words) : null;\n  }\n  // The control a click at this spot of the page presses, unless it lands on a field, label or nothing.\n  function pressedControl(hit) {\n    const field = "input:not([type=submit]):not([type=button]):not([type=image]):not([type=reset]), textarea, select, label, [contenteditable]";\n    for (let node = hit; node && node !== document.documentElement; node = node.parentElement || node.getRootNode().host) {\n      // A click on a label presses its control: a submit button pays, a field or anything else does not.\n      if (node instanceof HTMLLabelElement && node.control) {\n        const control = node.control;\n        return !control.matches?.(field) && (pressable(control) || control.matches?.("a, button, input, [role=button]"))\n          ? control : null;\n      }\n      if (node.matches?.(field)) return null;\n      if (pressable(node) || node.matches?.("a, button, input, [role=button]")) return node;\n    }\n    return null;\n  }\n  const FRAMES = ["iframe", "frame", "object", "embed"];\n  const hasFrames = () => Boolean(document.querySelector("iframe,frame"));\n  // The window\'s page starts below its toolbar. Calibrated for a window with the plain toolbar and no side\n  // panel or docked tools: anything else moves the page, so a spot cannot be placed.\n  const TOOLBAR_HEIGHT = 87;\n  window.__rakazoPurchase = {\n    // Where a point of the screen (x, y) is in this page, or null when that cannot be told (a zoomed page,\n    // a scaled screen, a window with more than the toolbar).\n    pagePoint(x, y) {\n      if (window.devicePixelRatio !== 1 || !Number.isFinite(x) || !Number.isFinite(y)) return null;\n      if (window.outerWidth !== window.innerWidth\n          || Math.abs(window.outerHeight - window.innerHeight - TOOLBAR_HEIGHT) > 2) return null;\n      const side = (window.outerWidth - window.innerWidth) / 2;\n      const at = [x - (window.screenX + side), y - (window.screenY + window.outerHeight - window.innerHeight - side)];\n      return { x: at[0], y: at[1], inside: at[0] >= 0 && at[1] >= 0 && at[0] < window.innerWidth && at[1] < window.innerHeight };\n    },\n    // What a click at a spot of this page (in viewport coordinates) would press: the purchase it completes, or\n    // `inFrame` when the spot is inside a frame, whose own page must be asked.\n    purchaseAt(x, y, frame = false) {\n      if (!(x >= 0 && y >= 0 && x < window.innerWidth && y < window.innerHeight)) return { offscreen: true };\n      const hit = elementAtPoint(x, y);\n      const inFrame = Boolean(hit) && FRAMES.includes(hit.tagName.toLowerCase());\n      const control = hit && !inFrame ? pressedControl(hit) : null;\n      return { purchase: control && !control.matches(":disabled") ? purchaseOf(control, frame) : null,\n        inFrame, scroll: [window.pageXOffset, window.pageYOffset], frames: hasFrames() };\n    },\n    // The same for a node the browser found at a spot inside a frame of this process.\n    purchaseOfNode(node, frame = false) {\n      const control = node instanceof Element ? pressedControl(node) : null;\n      return control && !control.matches(":disabled") ? purchaseOf(control, frame) : null;\n    },\n    // A click or key whose spot is not known: the page shows a card form or a payment frame, or a control\n    // worded as a final step. For a key (`enter`), the control with focus first.\n    paymentPage(frame = false, enter = false) {\n      const active = enter ? document.activeElement : null;\n      const typingIn = active?.form && [...active.form.elements].some(cardLike) ? active.form : null;\n      const submit = typingIn && [...typingIn.elements].find((el) => submittedForm(el) === typingIn);\n      const focused = typingIn ? shownPurchase("card_form", submit ? wordsOf(submit)[0] || "" : "")\n        : active && active !== document.body ? purchaseOf(pressedControl(active) || active, frame) : null;\n      if (focused) return { purchase: focused, frames: hasFrames() };\n      // Enter in a field submits only that field\'s form.\n      if (active?.matches?.("input, textarea, select")) {\n        const own = active.form && [...active.form.elements].find((el) => submittedForm(el) === active.form);\n        return { purchase: own ? purchaseOf(own, frame) : null, frames: hasFrames() };\n      }\n      const final = [...document.querySelectorAll("button, input, a, [role=button]")].find((el) =>\n        pressable(el) && visible(el) && !el.matches(":disabled") && isFinalStep(wordsOf(el), el));\n      const shown = Boolean(frame || pageCards().length || final);\n      return { purchase: shown ? shownPurchase("payment_page", final ? wordsOf(final)[0] || "" : "") : null,\n        frames: hasFrames() };\n    },\n  };\n  return true;\n})()\n"""\n\n# Zero-width, bidirectional and tag characters, which the card does not show.\nINVISIBLE = re.compile("[\\U000E0000-\\U000E007F​-‏⁠-⁤‪-‮⁦-⁩﻿]")\n# What the card shows when not even the page\'s own signals can be read: the check asks rather than allows.\nUNREADABLE_PURCHASE = {"reason": "unreadable", "label": "", "amount": "", "amountFrom": "page"}\nDESKTOP_DEADLINE_SECONDS = 8.0\n# Elements that hold another document.\nFRAME_ELEMENTS = ("IFRAME", "FRAME", "OBJECT", "EMBED")\n\n\ndef shown(text: Any) -> str:\n    """Page text as the card shows it: no invisible characters, one space between words."""\n    return " ".join(INVISIBLE.sub("", str(text or "")).split())\n\n\nclass Offscreen(RuntimeError):\n    """The control is out of view, so no spot of the page shows it."""\n\n\nclass Deadline(RuntimeError):\n    """The desktop check ran out of time."""\n\n\ndef check_deadline(deadline: float) -> None:\n    if time.monotonic() > deadline:\n        raise Deadline()\n\n\nclass Purchases:\n    """The tab\'s purchase checks, in page_secrets\' isolated world of each frame."""\n\n    def __init__(self, port: int, target: str) -> None:\n        self.client = page_secrets.connect(port)\n        try:\n            self.session = page_secrets.attach(self.client, target)\n        except Exception:\n            self.client.close()\n            raise\n\n    def close(self) -> None:\n        self.client.close()\n\n    def ask(self, session: str, world: int | None, call: str) -> Any:\n        return page_secrets.eval_json(self.client, session, f"{PURCHASE_HELPERS}, window.__rakazoPurchase.{call}",\n                                      context_id=world)\n\n    def where(self) -> dict[str, str]:\n        found = page_secrets.eval_json(self.client, self.session,\n                                       "({url: location.href, title: (document.title || \'\').slice(0, 200)})")\n        return {key: str(found.get(key) or "") for key in ("url", "title")} if isinstance(found, dict) else {}\n\n    def site(self) -> str:\n        """The top page\'s host. Each check starts here, in the world of the document the tab shows now: an\n        earlier step may have navigated."""\n        top = page_secrets.main_frame(self.client, self.session)["id"]\n        self.client.context_id = page_secrets.world_in(self.client, self.session, top)\n        host = page_secrets.eval_json(self.client, self.session, "location.host")\n        return host if isinstance(host, str) else ""\n\n    def asked_with_frames(self, session: str, world: int | None, call: str) -> dict[str, Any] | None:\n        """`call` (with a %s for whether the page shows a payment provider\'s frame), asked again with one."""\n        found = self.ask(session, world, call % "false")\n        if not isinstance(found, dict):\n            return None\n        if found.get("purchase") is None and found.get("frames"):\n            try:\n                frame = bool(page_secrets.payment_frames(self.client, session))\n            except Exception:  # noqa: BLE001\n                frame = False\n            if frame:\n                found = self.ask(session, world, call % "true")\n        return found if isinstance(found, dict) else None\n\n    def frames(self, deadline: float) -> list[tuple[str, int]]:\n        """Every frame of the page, of any origin, as (session, world): at most 32."""\n        sessions = [(self.session, False)]\n        try:\n            sessions += [(child, True) for child in page_secrets.auto_attach(self.client, self.session)]\n        except Exception:  # noqa: BLE001\n            pass\n        found: list[tuple[str, int]] = []\n        for session, own in sessions:\n            check_deadline(deadline)\n            try:\n                if own:\n                    self.client.call("Page.enable", session_id=session)\n                tree = self.client.call("Page.getFrameTree", session_id=session)["frameTree"]\n            except Exception:  # noqa: BLE001\n                continue\n            stack = [tree] if own else list(tree.get("childFrames") or [])\n            while stack and len(found) < 32:\n                node = stack.pop(0)\n                stack += node.get("childFrames") or []\n                check_deadline(deadline)\n                try:\n                    found.append((session, page_secrets.world_in(self.client, session, node["frame"]["id"])))\n                except Exception:  # noqa: BLE001\n                    continue\n        return found\n\n    def signals(self, enter: bool, deadline: float = float("inf"), frames: bool = True) -> dict[str, Any] | None:\n        """The purchase the page shows without a spot to look at: in the page itself, else in any of its frames."""\n        call = "paymentPage(%s, " + json.dumps(enter) + ")"\n        found = self.asked_with_frames(self.session, None, call)\n        if found and isinstance(found.get("purchase"), dict):\n            return found["purchase"]\n        for session, world in self.frames(deadline) if frames else []:\n            try:\n                inside = self.ask(session, world, call % "false")\n            except Exception:  # noqa: BLE001\n                continue\n            if isinstance(inside, dict) and isinstance(inside.get("purchase"), dict):\n                return inside["purchase"]\n        return None\n\n    def signals_or_ask(self, enter: bool) -> dict[str, Any] | None:\n        """After a failed check: the payment the page itself shows, and a page that cannot be read asks."""\n        try:\n            return self.signals(enter, frames=False)\n        except Exception:  # noqa: BLE001\n            return dict(UNREADABLE_PURCHASE)\n\n    def at_point(self, session: str, world: int | None, x: float, y: float, deadline: float,\n                 depth: int = 0) -> tuple[str, dict[str, Any] | None]:\n        """What a click at (x, y) of this page\'s viewport presses: ("buy", purchase), ("none", None) when it\n        lands on nothing that pays, or ("unknown", None) when a frame it lands in cannot be looked into."""\n        check_deadline(deadline)\n        client = self.client\n        try:\n            found = self.asked_with_frames(session, world, f"purchaseAt({json.dumps(x)}, {json.dumps(y)}, %s)")\n        except Exception:  # noqa: BLE001\n            return "unknown", None\n        if not found:\n            return "unknown", None\n        if found.get("offscreen"):\n            return ("offscreen" if depth == 0 else "unknown"), None\n        if isinstance(found.get("purchase"), dict):\n            return "buy", found["purchase"]\n        if not found.get("inFrame"):\n            return "none", None\n        if depth >= 3:\n            return "unknown", None\n        scroll_x, scroll_y = found.get("scroll") or [0, 0]\n        try:\n            # The browser\'s own hit-test, which counts from the top of the page and goes into frames of this process.\n            hit = client.call("DOM.getNodeForLocation", {"x": x + scroll_x, "y": y + scroll_y,\n                                                         "includeUserAgentShadowDOM": True}, session_id=session)\n            top = page_secrets.main_frame(client, session)["id"]\n            node = client.call("DOM.describeNode", {"backendNodeId": hit["backendNodeId"]}, session_id=session)["node"]\n            is_frame = str(node.get("nodeName", "")).upper() in FRAME_ELEMENTS\n            if hit.get("frameId") != top and not is_frame:\n                inner = page_secrets.world_in(client, session, hit["frameId"])\n                page_secrets.eval_json(client, session, PURCHASE_HELPERS, context_id=inner)\n                resolved = client.call("DOM.resolveNode", {"backendNodeId": hit["backendNodeId"],\n                                                           "executionContextId": inner}, session_id=session)\n                value = page_secrets.page_value(client.call("Runtime.callFunctionOn", {\n                    "objectId": resolved["object"]["objectId"], "returnByValue": True,\n                    "functionDeclaration": "function () { return window.__rakazoPurchase.purchaseOfNode(this, false); }",\n                }, session_id=session))\n                # Nothing paying in the frame itself: the page around it may still be the checkout.\n                return ("buy", value) if isinstance(value, dict) else ("unknown", None)\n            if not is_frame:\n                return "unknown", None\n            # A frame of another process: its own session answers, for the spot as that frame\'s page sees it.\n            for child in page_secrets.auto_attach(client, session):\n                check_deadline(deadline)\n                frame = page_secrets.main_frame(client, child)\n                owner = client.call("DOM.getFrameOwner", {"frameId": frame["id"]}, session_id=session)\n                if owner.get("backendNodeId") != hit["backendNodeId"]:\n                    continue\n                box = client.call("DOM.getBoxModel", {"backendNodeId": hit["backendNodeId"]},\n                                  session_id=session)["model"]["content"]\n                client.call("Page.enable", session_id=child)\n                inner = page_secrets.world_in(client, child, frame["id"])\n                # The box is where the frame is in the viewport, scroll included.\n                return self.at_point(child, inner, x - box[0], y - box[1], deadline, depth + 1)\n        except Deadline:\n            raise\n        except Exception:  # noqa: BLE001\n            return "unknown", None\n        return "unknown", None\n\n    def click(self, box: dict[str, Any] | None, scrolled: bool) -> dict[str, Any] | None:\n        """What a click on a control of the top page, at the middle of its box in the viewport, would buy.\n        Raises Offscreen for a control out of view the first time; one that cannot be looked at answers\n        with what the page itself shows."""\n        deadline = time.monotonic() + DESKTOP_DEADLINE_SECONDS\n        try:\n            x = float(box["x"]) + float(box["width"]) / 2  # type: ignore[index]\n            y = float(box["y"]) + float(box["height"]) / 2  # type: ignore[index]\n            verdict, found = self.at_point(self.session, None, x, y, deadline)\n        except Exception:  # noqa: BLE001\n            verdict, found = "unknown", None\n        if verdict == "offscreen" and not scrolled:\n            raise Offscreen()\n        if verdict in ("buy", "none"):\n            return found if verdict == "buy" else None\n        # The spot could not be looked into, perhaps a frame, or the control is still out of view: what the\n        # page or any of its frames shows decides, within the same time.\n        try:\n            return self.signals(False, deadline)\n        except Exception:  # noqa: BLE001\n            return dict(UNREADABLE_PURCHASE)\n\n    def desktop(self, args: dict[str, Any]) -> dict[str, Any] | None:\n        """The purchase a click or key on the screen would complete, or None.\n\n        Each click is looked up on the page at its spot and asks only when it lands on a control that pays; a\n        spot outside the browser window asks nothing. A key, or a spot that cannot be placed or looked into,\n        asks when the page shows a payment by itself.\n        """\n        deadline = time.monotonic() + DESKTOP_DEADLINE_SECONDS\n        enter = args.get("enter") is True\n        points = [(p["x"], p["y"]) for p in (args.get("points") or [])[:24]\n                  if isinstance(p, dict) and all(isinstance(p.get(k), (int, float)) for k in ("x", "y"))]\n        unknown = enter or not points or args.get("unplaced") is True\n        try:\n            for x, y in points:\n                placed = self.ask(self.session, None, f"pagePoint({json.dumps(x)}, {json.dumps(y)})")\n                if not isinstance(placed, dict):\n                    unknown = True\n                elif placed.get("inside"):\n                    verdict, found = self.at_point(self.session, None, placed["x"], placed["y"], deadline)\n                    if verdict == "buy":\n                        return found\n                    unknown = unknown or verdict != "none"\n            return self.signals(enter, deadline) if unknown else None\n        except Exception:  # noqa: BLE001\n            # Out of time, or a lookup failed: what the page itself already shows still asks.\n            return self.signals_or_ask(enter)\n\n\ndef purchase_refusal(step: dict[str, Any], site: str, buying: dict[str, Any] | None, completed: int) -> dict[str, Any] | None:\n    """Why a click that buys is not made: bought only on the user\'s word, for this site, while the button\n    and total still say what the card showed. An earlier step may have changed the page since the caller asked."""\n    if not buying:\n        return None\n    approved = step.get("approved") is True and step.get("site") == site\n    changed = approved and any(key in step and shown(step[key]) != shown(buying.get(key)) for key in ("label", "amount"))\n    if approved and not changed:\n        return None\n    return {"ok": False, "completed": completed, "uncertain": False, "purchase": {**buying, "site": site},\n            "error": PURCHASE_CHANGED if changed else PURCHASE_REFUSED}\n\n\ndef resolve_upload_paths(paths: Any, home: str | None = None, roots: list[str] | None = None) -> list[str]:\n    """Resolve regular files within trusted roots before handing them to Chromium."""\n    if not isinstance(paths, list) or not 1 <= len(paths) <= MAX_UPLOAD_FILES:\n        raise RuntimeError(f"upload needs 1 to {MAX_UPLOAD_FILES} file paths")\n    home = os.path.realpath(home or os.environ.get("HOME") or "/home/rakazo")\n    location = "your folder or shared/" if roots is not None else "this computer\'s home folder"\n    allowed = [home]\n    if roots is not None:\n        allowed = []\n        for root in roots:\n            expected = os.path.normpath(os.path.join(home, root))\n            full = os.path.realpath(expected)\n            # A root redirected by a symlink (bots/b1 -> bots/b2) could reach another bot\'s files.\n            if os.path.isabs(root) or full != expected or os.path.commonpath([home, full]) != home:\n                raise RuntimeError(f"Upload files must be inside {location}")\n            # A folder that does not exist yet holds no files; the other root still applies.\n            if os.path.isdir(full):\n                allowed.append(full)\n    max_bytes = max_file_bytes()\n    resolved = []\n    total = 0\n    for path in paths:\n        if not isinstance(path, str) or not path.strip():\n            raise RuntimeError("upload paths must be non-empty strings")\n        full = os.path.realpath(os.path.join(home, path))\n        # Check confinement before existence to avoid revealing outside targets.\n        if not any(os.path.commonpath([root, full]) == root for root in allowed):\n            raise RuntimeError(f"Upload files must be inside {location}: {path}")\n        try:\n            info = os.stat(full)\n        except OSError:\n            raise RuntimeError(f"File not found: {path}") from None\n        if not stat.S_ISREG(info.st_mode):\n            raise RuntimeError(f"Not a regular file: {path}")\n        total += info.st_size\n        if total > max_bytes:\n            raise RuntimeError(f"upload files are larger than {max_bytes / (1024 * 1024):g} MB in total")\n        resolved.append(full)\n    return resolved\n\n\ndef validate_actions(actions: Any) -> None:\n    """Every step is checked before any runs, so a bad one cannot leave a half-done form."""\n    if not isinstance(actions, list) or not actions or len(actions) > 24:\n        raise RuntimeError("Expected 1 to 24 actions")\n    for step in actions:\n        if not isinstance(step, dict) or step.get("kind") not in ("click", "fill", "type", "upload", "pay_token"):\n            raise RuntimeError("Invalid browser action")\n        if step["kind"] == "pay_token":\n            if (step.get("ref") is not None or not isinstance(step.get("text"), str) or not step["text"]\n                    or not isinstance(step.get("origin"), str) or not isinstance(step.get("merchantAccountId"), str)):\n                raise RuntimeError("A pay token needs its text, origin and merchant account, and no ref")\n            continue\n        if step.get("ref") is None and step["kind"] == "fill" and step.get("field") == "card":\n            if step.get("cardField") not in page_secrets.CARD_AUTOCOMPLETE:\n                raise RuntimeError("A card fill without a ref needs its card field")\n        elif not isinstance(step.get("ref"), str) or not re.fullmatch(r"e\\d+", step["ref"]):\n            raise RuntimeError("Element ref is required")\n        if step["kind"] == "upload":\n            step["files"] = resolve_upload_paths(step.get("paths"), roots=step.get("roots"))\n        elif step["kind"] != "click" and not isinstance(step.get("text"), str):\n            raise RuntimeError("Text is required")\n        if step.get("origin") is not None and (step["kind"] != "fill" or not isinstance(step["origin"], str)):\n            raise RuntimeError("An origin applies only to fill")\n        if ("approved" in step or "site" in step) and (\n                step["kind"] != "click" or not isinstance(step.get("approved"), bool)\n                or not isinstance(step.get("site"), str)):\n            raise RuntimeError("An approval applies only to click, with the site it was given for")\n        if ("label" in step or "amount" in step) and (\n                step["kind"] != "click" or not isinstance(step.get("approved"), bool)\n                or not all(isinstance(step.get(key, ""), str) for key in ("label", "amount"))):\n            raise RuntimeError("An approved label and amount apply only to an approved click")\n        # A card detail is hidden and checked only on an origin-bound fill.\n        if step.get("field") == "card" and not step.get("origin"):\n            raise RuntimeError("A card fill needs its origin")\n        if step.get("origin") and not step.get("field"):\n            raise RuntimeError("A saved login fill needs its field")\n\n\ndef exit_when_stdin_closes() -> None:\n    """The supervisor owns this pipe; losing it cancels this helper, not Chromium."""\n    try:\n        while os.read(0, 1024):\n            pass\n    finally:\n        os._exit(130)\n\n\ndef read_stdin_line() -> str:\n    """Read one line from fd 0 unbuffered, leaving the rest of stdin for the EOF watcher."""\n    data = bytearray()\n    while len(data) < 1_048_576:\n        chunk = os.read(0, 1)\n        if not chunk or chunk == b"\\n":\n            break\n        data += chunk\n    return data.decode("utf-8")\n\n\ndef run_operation(client: CdpClient, port: int, browser: AgentBrowser, command: str,\n                  args: dict[str, Any], downloads: Downloads | None = None,\n                  tabs: Tabs | None = None) -> dict[str, Any]:\n    """Keep the fork\'s bounded recovery while agent-browser owns page reading and actions."""\n    browser.client = client\n    opened_target: str | None = None\n    page: PageBrowser | None = None\n\n    def attach_page(connection: CdpClient) -> str:\n        nonlocal opened_target\n        target, address = front_tab(port)\n        if internal(address):\n            if command != "navigate":\n                raise RuntimeError(INTERNAL_PAGE)\n            url = str(args.get("url") or "")\n            check_url(url)\n            (tab,) = browser.batch([["tab", "new", url]], timeout=NAVIGATE_SECONDS)\n            if urlsplit(address).netloc in ("newtab", "new-tab-page"):\n                urllib.request.urlopen(f"http://127.0.0.1:{port}/json/close/{target}", timeout=5.0).close()\n            # A pop-up may already be in front: attach to the tab this navigation opened by id.\n            target = str(tab.get("targetId") or "") or front_tab(port)[0]\n            # Read the site just opened instead of navigating it again before its request log starts.\n            opened_target = target\n        session = connection.call("Target.attachToTarget", {"targetId": target, "flatten": True})["sessionId"]\n        browser.session_id = session\n        return session\n\n    def operate(connection: CdpClient, session: str, value: Any = None) -> dict[str, Any]:\n        nonlocal page\n        browser.session_id = session\n        target = connection.call("Target.getTargetInfo", session_id=session)["targetInfo"]["targetId"]\n        browser.use_tab(target)\n        page = PageBrowser(port, target, browser, connection, session)\n        if downloads:\n            frame = connection.call("Page.getFrameTree", session_id=session)["frameTree"]["frame"]\n            connection.download_frame = frame["id"]\n            connection.call("Network.enable", {"maxPostDataSize": 1}, session_id=session)\n            page.downloads = downloads\n        try:\n            if command == "navigate":\n                return page.navigate(value, opened=target == opened_target)\n            if command == "snapshot":\n                query = args.get("query")\n                return page.snapshot(query=query.strip()[:200] if isinstance(query, str) and query.strip() else None)\n            return page.act(value)\n        except Exception:  # noqa: BLE001\n            dialog = page.dialog()\n            if dialog:\n                return page.dialog_result(dialog, {})\n            raise\n        finally:\n            page.close()\n\n    # A replacement tab needs no old CDP page driver: agent-browser initializes its own page.\n    api = {"attach_page": attach_page, "ensure_world": lambda connection, session: None,\n           "navigate": operate, "snapshot": operate, "act": operate}\n    result = recovery.run_operation(api, client, command, args)\n    if page is None:\n        return result\n    # Recovery may replace the original tab. Track and re-read the page it actually operated on.\n    target = page.target\n    if tabs is not None:\n        closed = tabs.closed\n        now: list[dict[str, Any]] = []\n        new: list[dict[str, Any]] = []\n        browser.deadline = tabs.deadline = tab_deadline()\n        try:\n            now, new, _ = tabs.end(target, ours=opened_target)\n        except Exception:  # noqa: BLE001\n            pass  # The tabs it closed before failing are still counted below.\n        try:\n            if tabs.closed > closed and any(key in result for key in ("url", "tree")):\n                # Never return page content or a dialog read from a tab that has been closed.\n                for key in ("url", "title", "tree", "elements", "frameOrigins", "loading", "note", "dialog"):\n                    result.pop(key, None)\n                try:\n                    browser.use_tab(target)\n                    result.update(page.snapshot(0.0))\n                except Exception:  # noqa: BLE001\n                    result.update(ok=False, error=REREAD_FAILED,\n                                  **({"uncertain": False} if command == "act" else {}))\n        finally:\n            browser.deadline = None\n        note = tabs.note(now, new, result.get("url"))\n        if note:\n            result["note"] = " ".join(filter(None, [result.get("note"), note]))\n    if downloads:\n        front: dict[str, Any] = {}\n        with contextlib.suppress(Exception):\n            front = page_tabs(port)[0]\n        page.save_pdf(front)\n    return result\n\n\ndef tab_deadline() -> float:\n    return min(time.monotonic() + TAB_WORK_SECONDS, STARTED + TABS_DONE_BY)\n\n\ndef run(argv: list[str]) -> int:\n    stdin_args = read_stdin_line() if os.environ.get("RAKAZO_BROWSER_ARGS_STDIN") == "1" else None\n    if os.environ.get("RAKAZO_BROWSER_WATCH_STDIN") == "1":\n        threading.Thread(target=exit_when_stdin_closes, daemon=True).start()\n    if len(argv) < 2:\n        print(json.dumps({"ok": False, "error": "usage: rakazo-page-browser <command> [json-args]",\n                          "fallback": "computer_act"}))\n        return 2\n    command = argv[1]\n    if command not in ("navigate", "snapshot", "act", "restart", "finish", "purchase_check"):\n        print(json.dumps({"ok": False, "error": f"unknown command: {command}", "fallback": "computer_act"}))\n        return 2\n    raw_args = stdin_args if stdin_args is not None else (argv[2] if len(argv) >= 3 else "")\n    args: dict[str, Any] = json.loads(raw_args) if raw_args.strip() else {}\n    if command == "finish":\n        try:\n            finish_later(args.get("downloads") or [])\n        except (OSError, RuntimeError):\n            print(json.dumps({"downloads": [{"error": DOWNLOAD_FAILED}]}))\n            return 1\n        return 0\n    port = cdp_port()\n    downloads: Downloads | None = None\n    client: CdpClient | None = None\n    saved: list[dict[str, Any]] = []\n    # Set once the browser answers: before that, no action can have reached the page.\n    connected = False\n    try:\n        if command == "restart":\n            result = recovery.restart_browser(port, wait_for_cdp, lambda: CdpClient(discover_ws_url(port)))\n            print(json.dumps(result))\n            return 0\n        if command == "purchase_check":\n            # No browser running, no tab open, or one of Chromium\'s own pages: nothing on it can be bought.\n            # Any other failure is a failed check, which asks.\n            try:\n                # A closed browser has nothing to buy, and a desktop press waits on this check, so it is\n                # told apart at once; a browser that is only slow is waited for, and failing still asks.\n                address = ""\n                if not browser_closed(port):\n                    wait_for_cdp(port)\n                    target, address = front_tab(port)\n            except RuntimeError as error:\n                if str(error) != NO_TAB:\n                    raise\n                address = ""\n            if not address or internal(address):\n                print(json.dumps({"ok": True, "site": "", "purchase": None, "url": address, "title": ""}))\n                return 0\n            # Check the current tab without recovery replacing it or tab cleanup changing the page.\n            # A check that fails must ask, never succeed by reading a fresh, empty tab.\n            browser = AgentBrowser(port)\n            browser.use_tab(target)\n            page = PageBrowser(port, target, browser)\n            try:\n                result = page.purchase_check(args)\n            finally:\n                page.close()\n            print(json.dumps(result))\n            return 0\n        version = wait_for_cdp(port)\n        client = CdpClient(discover_ws_url(port))\n        client.connect()\n        connected = True\n        browser = AgentBrowser(port)\n        tabs: Tabs | None = None\n        # Best effort here and below: a tab list that fails leaves the call as it was.\n        with contextlib.suppress(Exception):\n            started = Tabs(browser.home, port, (version or {}).get("webSocketDebuggerUrl"), browser.use_tab)\n            browser.deadline = started.deadline = tab_deadline()\n            try:\n                started.begin()\n            finally:\n                browser.deadline = None\n            # Only once it knows the tabs the call began with: without them, every tab would look new.\n            tabs = started\n        if args.get("downloads") is not None:\n            downloads = Downloads(client, args["downloads"])\n        result = run_operation(client, port, browser, command, args, downloads, tabs)\n        if downloads:\n            client.listen(0.01)\n            saved = downloads.finish()\n            downloads = None\n        print(json.dumps({**result, **({"downloads": saved} if saved else {})}))\n        return 0  # Structured failures preserve partial action progress.\n    except Exception as exc:  # noqa: BLE001\n        if downloads:\n            try:\n                client.listen(0.01)\n                saved = downloads.finish()\n            except Exception:\n                saved = [{"error": DOWNLOAD_FAILED}]\n        print(json.dumps({"ok": False, "error": recovery.TIMEOUT_MESSAGE if isinstance(exc, TimeoutError) else str(exc),\n                          "fallback": "computer_act",\n                          "uncertain": command == "act" and connected, **({"downloads": saved} if saved else {})}))\n        return 0\n    finally:\n        if client:\n            client.close()\n\n\nif __name__ == "__main__":\n    sys.exit(run(sys.argv))\n';
